const e=[{id:1,icon:"Flame",emoji:"🔥",accent:"#dc2626",title:"مەترسییەکانی ئاگر",subtitle:"ئاگادار بە و خۆت بپارێزە",summary:"ئاگر زۆر بەسوودە بۆ لێنانی خواردن و گەرمکردنەوەی ماڵ، بەڵام ئەگەر وریا نەبین، دەتوانێت زیانی گەورەمان پێ بگەیەنێت. فێربوونی یاساکانی ئاگر نیشانەی زیرەکیی تۆیە!",blocks:[{heading:"شقارتە و چەقماخە بۆ یاری نین",body:"شقارتە و چەقماخە تەنها بۆ گەورەکانن. یاریکردن پێیان دەتوانێت یەکسەر ئاگرێک هەڵبکات و بتسووتێنێت.",image:"media/images/fire_danger_1.png"},{heading:"لە سۆبە دوور بکەوەرەوە",body:"لانیکەم سێ هەنگاو لە سۆبە و هەر ئامێرێکی گەرمکردنەوە دوور بمێنەوە، بۆ ئەوەی جلەکانت ئاگر نەگرن.",image:"media/images/fire_danger_2.png"},{heading:"ڕاوەستە، بکەوە سەر زەوی، خۆت بگلێنە",body:"ئەگەر ئاگر بەر جلەکانت کەوت: ڕامەکە! ڕاوەستە، بکەوە سەر زەوی، دەم و چاوت بە دەستەکانت دابپۆشە و لەسەر زەوی خۆت بگلێنە تا ئاگرەکە دەکوژێتەوە. پاشان بە دەنگی بەرز بانگی کەسێکی گەورە بکە.",image:"media/images/fire_danger_3.png"}],examples:["کاتێک ئاگرێک دەبینیت، بە دەنگی بەرز هاوار بکە: ئاگر! ئاگر! و لەو شوێنە دوور بکەوەرەوە.","هەرگیز یاری بە چەقماخە مەکە، تەنانەت ئەگەر کوژاوەش بێت.","ئەگەر دووکەڵ لە ژوورەکەدا هەبێت، خۆت نزم بکەرەوە و لەسەر دەست و ئەژنۆ بە گاگۆڵکێ بەرەو دەرەوە بڕۆ."],video:"media/videos/lesson02_fire.mp4",game:{instruction:"کام لەم شتانە مەترسیدارن؟",items:[{text:"شقارتە",emoji:"🔥",correct:!0},{text:"بووکەڵە",emoji:"🧸",correct:!1},{text:"سۆبەی گاز",emoji:"♨️",correct:!0},{text:"کتێب",emoji:"📚",correct:!1}]},activity:{prompt:"دەچیتە چێشتخانە و دەبینیت پارچە قوماشێک کەوتووەتە سەر تەباخەکە و دەسووتێت، چی دەکەیت؟",image:"media/images/activity_fire.png",options:[{text:"لە چێشتخانە دەچمە دەرەوە و بە دەنگی بەرز بە دایکم یان باوکم دەڵێم",correct:!0,feedback:"ئاگر مەترسیدارە، بۆیە دوور دەکەویتەوە و بە دەنگی بەرز بانگی کەسێکی گەورە دەکەیت!"},{text:"هەوڵ دەدەم بە دەستەکانم بیکوژێنمەوە",correct:!1,feedback:"ئاگر دەست دەسووتێنێت، هەرگیز دەستی لێ مەدە، بچۆ دەرەوە و بە کەسێکی گەورە بڵێ."},{text:"لەوێ ڕادەوەستم و سەیر دەکەم",correct:!1,feedback:"مانەوە لە نزیک ئاگر مەترسیدارە، دوور بکەوەرەوە و بە کەسێکی گەورە بڵێ."},{text:"خۆم دەشارمەوە",correct:!1,feedback:"خۆت مەشارەوە، بچۆ دەرەوە و بە دەنگی بەرز بانگی دایکت یان باوکت بکە."}]}},{id:2,icon:"Zap",emoji:"⚡",accent:"#ca8a04",title:"مەترسییەکانی کارەبا",subtitle:"کارەبا یاری نییە، وریا بە",summary:"کارەبا هێزێکی نەبینراوە کە گڵۆپ و تەلەفزیۆنەکانمان پێی کار دەکەن. ئەم هێزە زۆر بەسوودە، بەڵام ئەگەر بە شێوەیەکی هەڵە دەستی لێ بدەین، دەتوانێت زیانێکی گەورە بە دڵ و لەشمان بگەیەنێت.",blocks:[{heading:"دەست لە پلاکی کارەبا مەدە",body:"پلاکی کارەبا تەنها بۆ وایەری ئامێرەکانی ماڵە. هەرگیز مووروو، قەڵەم یان شتی ئاسنین مەخەرە ناو پلاکەوە، چونکە کارەبا دەتگرێت.",image:"media/images/electricity_1.png"},{heading:"ئاو و کارەبا دوژمنی یەکترن",body:"ئاو کارەبا بە خێرایی دەگوازێتەوە. هەرگیز بە دەستی تەڕ، یان کاتێک لە حەمامدایت، دەست لە سویچ و وایەری کارەبا مەدە.",image:"media/images/electricity_2.png"},{heading:"وایەری بڕاو و ستوونی کارەبا",body:"ئەگەر وایەرێکی بڕاوت لەسەر شەقام یان لە ماڵەوە بینی، لێی نزیک مەبەرەوە و یەکسەر بە کەسێکی گەورە بڵێ. هەروەها لە کاتی باراندا دەست لە ستوونی کارەبای سەر شەقامەکان مەدە.",image:"media/images/electricity_3.png"}],examples:["هەرگیز وایەری شەحنی مۆبایل مەخەرە دەمتەوە.","وایەری مۆبایل و ئایپاد لە پلاک مەکێشە، بە کەسێکی گەورە بڵێ با ئەو دەری بهێنێت.","ئەگەر بینیت وایەرێک پریشک دەهاوێت یان بۆنێکی ناخۆشی لێ دێت، یەکسەر بە دایکت یان باوکت بڵێ."],video:"media/videos/lesson02_electricity.mp4",game:{instruction:"کام لەم کارانە سەلامەتن؟",items:[{text:"یاریکردن بە ئۆتۆمبێلی پلاستیکی",emoji:"🚗",correct:!0},{text:"دەستدان لە وایەرێکی بڕاو",emoji:"⚡",correct:!1},{text:"نووسین بە قەڵەم ڕەساس",emoji:"✏️",correct:!0},{text:"خستنی بزمارێکی ئاسنین بۆ ناو پلاک",emoji:"🔌",correct:!1}]},activity:{prompt:"بینیت برا بچووکەکەت لەسەر زەوییە و دەیەوێت وایەری شەحنی مۆبایل بخاتە دەمییەوە، چی دەکەیت؟",image:"media/images/activity_electricity.png",options:[{text:"یەکسەر بە دەنگی بەرز بانگی گەورەکان دەکەم بۆ ئەوەی وایەرەکەی لێ دوور بخەنەوە",correct:!0,feedback:"وایەر لە دەمدا مەترسیدارە، بۆیە بە خێرایی بانگی گەورەکان دەکەیت!"},{text:"چاوەڕێ دەکەم تا خۆی دەری دەهێنێت",correct:!1,feedback:"چاوەڕێکردن سەلامەت نییە، یەکسەر بە دەنگی بەرز بانگی گەورەکان بکە."},{text:"منیش لەگەڵیدا یاری پێ دەکەم",correct:!1,feedback:"کارەبا یاری نییە، بانگی کەسێکی گەورە بکە بۆ ئەوەی وایەرەکەی لێ دوور بخاتەوە."},{text:"خۆم دەشارمەوە",correct:!1,feedback:"خۆشاردنەوە یارمەتیی براکەت نادات، یەکسەر بانگی گەورەکان بکە."}]}},{id:3,icon:"TrafficCone",emoji:"🚦",accent:"#2563eb",title:"شەقام و ئۆتۆمبێل",subtitle:"سەلامەتیی تۆ لەسەر شەقام",summary:"شەقام شوێنی هاتوچۆی ئۆتۆمبێلی گەورە و خێرایە. بۆ ئەوەی پارێزراو بین، پێویستە یاساکانی هاتوچۆ باش فێر ببین و هەرگیز بە تەنیا نەچینە سەر شەقام.",blocks:[{heading:"دەستی گەورەکان بگرە",body:"کاتێک دەچیتە دەرەوە، هەمیشە دەستی دایکت، باوکت یان کەسێکی گەورە بگرە، بۆ ئەوەی پارێزراو بیت و ئۆتۆمبێلەکان بتبینن.",image:"media/images/traffic_1.png"},{heading:"سەیرکردنی شەقام (چەپ و ڕاست)",body:"پێش ئەوەی لەگەڵ کەسێکی گەورە لە شەقام بپەڕیتەوە، ڕاوەستە! سەیری لای چەپ بکە، پاشان لای ڕاست، پاشان جارێکی تر لای چەپ. ئەگەر هیچ ئۆتۆمبێلێک نەدەهات، ڕاستەوخۆ بپەڕەوە؛ ڕامەکە و لە ناو شەقامدا مەوەستە.",image:"media/images/traffic_2.png"},{heading:"زمانی گڵۆپەکانی هاتوچۆ",body:"لە شوێنی پەڕینەوەی پیادەڕەوان، سەیری ئەو گڵۆپە بکە کە وێنەی مرۆڤێکی بچووکی تێدایە. مرۆڤی سوور: ئێمە چاوەڕێ دەکەین. مرۆڤی سەوز: سەیری چەپ، ڕاست و دیسان چەپ دەکەین، پاشان دەستی کەسێکی گەورە دەگرین و دەپەڕینەوە. هەمیشە لەسەر هێڵی پەڕینەوەی پیادە (زێبرا) بپەڕەوە.",image:"media/images/traffic_3.png"}],examples:["هەرگیز لەسەر شەقام یاری بە تۆپ یان سکووتەر مەکە.","لە ناو ئۆتۆمبێلدا، هەمیشە پشتێنی سەلامەتی ببەستە.","لە پشت ئۆتۆمبێلی ڕاوەستاو یاری مەکە، چونکە کاتێک شۆفێر ئۆتۆمبێلەکە دەباتە دواوە، تۆ نابینێت."],video:"media/videos/lesson03_traffic.mp4",game:{instruction:"لەسەر گڵۆپی پیادەڕەوان، کام مرۆڤ پێت دەڵێت: چاوەڕێ بکە؟",items:[{text:"مرۆڤی سەوز (لەگەڵ کەسێکی گەورە بپەڕەوە)",emoji:"🟢",correct:!1},{text:"مرۆڤی سوور (چاوەڕێ بکە)",emoji:"🔴",correct:!0}]},activity:{prompt:"تۆپەکەت خلۆر بووەوە و چووە ناوەڕاستی شەقام و ئۆتۆمبێلێکی زۆر هەیە، چی دەکەیت؟",image:"media/images/activity_traffic.png",options:[{text:"بەدوایدا ناچم و یەکسەر بانگی کەسێکی گەورە دەکەم بۆ ئەوەی یارمەتیم بدات",correct:!0,feedback:"ئۆتۆمبێلەکان گەورە و خێران، بۆیە ناچیتە سەر شەقام و بانگی کەسێکی گەورە دەکەیت!"},{text:"بە خێرایی بەدوای تۆپەکەدا ڕادەکەم",correct:!1,feedback:"لەسەر شەقام ئۆتۆمبێلی گەورە و خێرا هەن، هەرگیز بە تەنیا مەچۆ، بانگی کەسێکی گەورە بکە."},{text:"چاوەڕێ دەکەم تا ئۆتۆمبێلێک تۆپەکە دەتەقێنێتەوە",correct:!1,feedback:"کەسێکی گەورە دەتوانێت بە سەلامەتی تۆپەکەت بۆ بهێنێت، یەکسەر بانگی بکە."},{text:"دەگریم و هاوار دەکەم",correct:!1,feedback:"گریان یارمەتی نادات، مەچۆ سەر شەقام و بانگی کەسێکی گەورە بکە."}]}},{id:4,icon:"Home",emoji:"🏠",accent:"#16a34a",title:"بوومەلەرزە",subtitle:"چۆنیەتیی خۆپاراستن",summary:"هەندێک جار زەوی دەلەرزێت. ئەمە دیاردەیەکی سروشتییە و پێی دەڵێن بوومەلەرزە. پێویستە هێمن بین و بزانین چۆن خۆمان بپارێزین.",blocks:[{heading:"لەسەر ئەژنۆ دابنیشە، خۆت بپارێزە، توند بیگرە (Drop, Cover, Hold On)",body:"ئەگەر زەوی لەرزی، یەکسەر لەسەر ئەژنۆ دابنیشە، بچۆ ژێر مێزێکی قایم، سەرت بپارێزە و قاچی مێزەکە باش بگرە تا لەرزینەکە ڕادەوەستێت.",image:"media/images/earthquake_1.png"},{heading:"لە شووشە و پەنجەرە دوور بکەوەرەوە",body:"لە کاتی بوومەلەرزەدا، شووشەی پەنجەرە و ئاوێنە دەتوانن بشکێن و بریندارت بکەن، بۆیە لێیان دوور بکەوەرەوە.",image:"media/images/earthquake_2.png"},{heading:"ڕامەکە بۆ دەرەوە و ئاسانسۆر بەکار مەهێنە",body:"لە کاتی لەرزینەکەدا، ڕاکردن بۆ دەرەوە مەترسیدارە، چونکە لەوانەیە شت لە باڵەخانەکەوە بکەوێتە سەرت. هەروەها هەرگیز ئاسانسۆر بەکار مەهێنە.",image:"media/images/earthquake_3.png"}],examples:["ئەگەر مێز نەبوو، لە پاڵ دیوارێکی دوور لە پەنجەرەکان لەسەر ئەژنۆ دابنیشە و بە دەستەکانت سەر و ملت بپارێزە.","هێمن بە و قیژە مەکە، چونکە ترس کارەکەت قورس دەکات.","دوای ئەوەی لەرزینەکە ڕاوەستا، هێواش هێواش و لەگەڵ گەورەکان لە باڵەخانەکە بچۆ دەرەوە."],video:"media/videos/lesson04_earthquake.mp4",game:{instruction:"لە کاتی بوومەلەرزەدا، کام لەم شوێنانە بۆ خۆپاراستن سەلامەتە؟",items:[{text:"لە ژێر مێزێکی قایم",emoji:"🪑",correct:!0},{text:"نزیک پەنجەرە شووشەییەکان",emoji:"🪟",correct:!1},{text:"ناو ئاسانسۆر",emoji:"🛗",correct:!1},{text:"لەسەر بانی ماڵ",emoji:"🏠",correct:!1}]},activity:{prompt:"تۆ لە ژوورەوەیت و ماڵەکە دەستی کرد بە لەرزین، چی دەکەیت؟",image:"media/images/activity_earthquake.png",options:[{text:"دەچمە ژێر مێزەکە، سەرم دەپارێزم و قاچی مێزەکە دەگرم",correct:!0,feedback:"مێزی قایم سەرت لەو شتانەی دەکەون دەپارێزێت، ئافەرین!"},{text:"بە ڕاکردن بەرەو دەرگای دەرەوە دەچم",correct:!1,feedback:"ڕاکردن لە کاتی لەرزیندا مەترسیدارە، لەوانەیە شت بکەونە سەرت، بچۆ ژێر مێزەکە."},{text:"دەگریم و بە تەنیا ڕادەوەستم",correct:!1,feedback:"بە تەنیا ڕاوەستان سەلامەت نییە، بچۆ ژێر مێزێکی قایم و قاچەکەی بگرە."},{text:"دەچمە بەر پەنجەرەکە و سەیری دەرەوە دەکەم",correct:!1,feedback:"شووشەی پەنجەرە دەتوانێت بشکێت و بریندارت بکات، بچۆ ژێر مێزەکە."}]}},{id:5,icon:"Scissors",emoji:"✂️",accent:"#9333ea",title:"شتە تیژ و بریندارکەرەکان",subtitle:"لەشی خۆت بپارێزە",summary:"چەقۆ، مقەست و هەموو شتە تیژەکان دەتوانن بە ئاسانی پێستمان ببڕن و خوێنی لێ بێت. ئەم شتانە بۆ یاری نین و تەنها بە وریاییەوە بەکار دەهێنرێن.",blocks:[{heading:"چەقۆ تەنها بۆ گەورەکانە",body:"چەقۆی چێشتخانە زۆر تیژن و تەنها گەورەکان بەکاریان دەهێنن. هەرگیز هەوڵ مەدە بە تەنیا شتێک بە چەقۆ ببڕیت.",image:"media/images/sharp_1.png"},{heading:"مقەستی سەلامەتی بۆ منداڵان",body:"ئەگەر مقەست بۆ کاری قوتابخانە بەکار دەهێنیت، دەبێت سەری خڕ بێت و تایبەت بێت بە منداڵان، بۆ ئەوەی بریندار نەبیت.",image:"media/images/sharp_2.png"},{heading:"شووشە و پارچە شکاوەکان",body:"ئەگەر پەرداخێک یان ئاوێنەیەک شکا، بە هیچ شێوەیەک دەستی لێ مەدە و پێی لێ مەنێ. یەکسەر لەو شوێنە دوور بکەوەرەوە و بە کەسێکی گەورە بڵێ، چونکە پارچە بچووکەکانی شووشە زۆر مەترسیدارن.",image:"media/images/sharp_3.png"}],examples:["هەرگیز بە شتێکی تیژەوە ڕامەکە.","دەرزی و سنجاقەکانی دایکت بۆ یاری نین، دەستیان لێ مەدە.","ئەگەر بریندار بوویت، یەکسەر بە گەورەکان بڵێ بۆ ئەوەی چارەسەرت بکەن."],video:"media/videos/lesson05_sharp.mp4",game:{instruction:"کام لەم شتانە مەترسیدارن و نابێت دەستیان لێ بدەین؟",items:[{text:"چەقۆ",emoji:"🔪",correct:!0},{text:"تۆپ",emoji:"⚽",correct:!1},{text:"قەڵەمی ڕەنگاوڕەنگ",emoji:"✏️",correct:!1},{text:"بووکەڵە",emoji:"🧸",correct:!1}]},activity:{prompt:"دەبینیت پەرداخێکی ئاو لەسەر زەوی شکاوە و کەس لەوێ نییە، چی دەکەیت؟",image:"media/images/activity_sharp.png",options:[{text:"لەو شوێنە دوور دەکەومەوە و دەچمە لای دایکم یان باوکم و پێیان دەڵێم بۆ ئەوەی پاکی بکەنەوە",correct:!0,feedback:"پارچە شووشە تیژە، بۆیە دوور دەکەویتەوە و بە کەسێکی گەورە دەڵێیت!"},{text:"بە دەستەکانم پارچە شووشەکان کۆ دەکەمەوە",correct:!1,feedback:"پارچە شووشە دەست بریندار دەکات، هەرگیز دەستی لێ مەدە، بە کەسێکی گەورە بڵێ."},{text:"پێی لێ دەنێم بۆ ئەوەی بزانم تیژە یان نا",correct:!1,feedback:"شووشە دەتوانێت پێت بریندار بکات، هەرگیز پێی لێ مەنێ، بە کەسێکی گەورە بڵێ."},{text:"دەیخەمە ژێر فەرشەکە بۆ ئەوەی کەس نەیبینێت",correct:!1,feedback:"دەست لە شووشەکە مەدە، بە کەسێکی گەورە بڵێ بۆ ئەوەی پاکی بکاتەوە."}]}},{id:6,icon:"CookingPot",emoji:"🍳",accent:"#ea580c",title:"چێشتخانەی سەلامەت",subtitle:"شوێنی خواردنە، نەک شوێنی یاری",summary:"چێشتخانە ئەو شوێنەی ماڵە کە خواردنی خۆشی تێدا ئامادە دەکرێت، بەڵام پڕە لە گەرمی، ئاگر و ئاوی کوڵاو کە دەتوانن زیانمان پێ بگەیەنن.",blocks:[{heading:"تەباخ و فڕن گەرمن",body:"کاتێک تەباخ داگیرساوە، لێی نزیک مەبەرەوە. گەرمییەکەی دەتوانێت بتسووتێنێت، تەنانەت ئەگەر دەستیشی لێ نەدەیت.",image:"media/images/kitchen_1.png"},{heading:"مەنجەڵەکانی سەر تەباخ",body:"هەرگیز دەست لە دەسکی مەنجەڵەکان مەدە و مەیانکێشە. گەورەکان دەسکەکان بەرەو ناوەوەی تەباخەکە دەسووڕێننەوە، بۆ ئەوەی مەنجەڵەکان نەکەون و ئاوی کوڵاو نەڕژێتە سەرت.",image:"media/images/kitchen_2.png"},{heading:"چێشتخانە شوێنی یاری نییە",body:"یاریکردن لە ناو چێشتخانە مەترسیدارە، چونکە لەوانەیە بکەویتە سەر تەباخ یان چەقۆیەک. باشترین شوێن بۆ یاری ژوورەکەی خۆتە یان هۆڵی ماڵەکەیە.",image:"media/images/kitchen_3.png"}],examples:["هەرگیز دەست لە فڕنی گەرم مەدە کاتێک نانی تێدا دروست دەکرێت.","ئاگاداری ئاوی کوڵاو و چای گەرم بە، دەتوانن بتسووتێنن!","لە ناو چێشتخانە ڕامەکە، چونکە زۆر جار زەوییەکەی خلیسکاوە."],video:"media/videos/lesson06_kitchen.mp4",game:{instruction:"کام لەم شوێنانە بۆ یاریکردن بە تۆپ گونجاوە؟",items:[{text:"هۆڵی ماڵ",emoji:"🛋️",correct:!0},{text:"سەر تەباخ",emoji:"🍳",correct:!1},{text:"باخچەی ماڵ",emoji:"🌳",correct:!0},{text:"ناو مەنجەڵی خواردن",emoji:"🍲",correct:!1}]},activity:{prompt:"دایکت لە چێشتخانە خواردن ئامادە دەکات و تەباخەکە داگیرساوە، لە کوێ یاری دەکەیت؟",image:"media/images/activity_kitchen.png",options:[{text:"دەچمە ژوورەکەی خۆم یان لە هۆڵەکە بە هێمنی یاری دەکەم",correct:!0,feedback:"چێشتخانە شوێنی یاری نییە، بۆیە ژوورەکەت شوێنێکی باشە بۆ یاری!"},{text:"دەچمە نزیک تەباخەکە و یاری دەکەم",correct:!1,feedback:"گەرمیی تەباخ دەتوانێت بتسووتێنێت، لە ژوورەکەت یاری بکە."},{text:"دەست لە مەنجەڵەکان دەدەم بۆ ئەوەی بزانم چی تێدایە",correct:!1,feedback:"مەنجەڵ دەتوانێت ئاوی کوڵاو بڕژێنێتە سەرت، هەرگیز دەستیان لێ مەدە."},{text:"لە ناو چێشتخانە تۆپ هەڵدەدەم",correct:!1,feedback:"لەوانەیە بکەویتە سەر تەباخ، لە ژوورەکەت یاری بە تۆپ بکە."}]}},{id:7,icon:"PlugZap",emoji:"💧",accent:"#0891b2",title:"ئاو و کارەبا: دوو دوژمنی گەورە",subtitle:"خۆت لە کارەباگرتن بپارێزە",summary:"ئاو و کارەبا هەرگیز نابێت بگەنە یەک. ئاو کارەبا بە خێرایی دەگوازێتەوە، و ئەگەر لەشت تەڕ بێت، کارەبا بە هێزتر دەتگرێت و زیانی گەورە بە دڵت دەگەیەنێت.",blocks:[{heading:"هەمیشە بە دەستی وشک",body:"پێش ئەوەی دەست لە سویچێکی کارەبا بدەیت، دەبێت دەستەکانت بە تەواوی وشک بن و هیچ ئاوێکیان پێوە نەبێت.",image:"media/images/water_elec_1.png"},{heading:"حەمام و ئامێرە ئەلیکترۆنییەکان",body:"هەرگیز مۆبایل، ئایپاد یان هەر ئامێرێک کە بە کارەبا کار دەکات مەبە ناو حەمام، بەتایبەتی کاتێک بە شەحنەوەیە، چونکە ئاو و هەڵم دەتوانن کارەبا بە تۆ بگەیەنن.",image:"media/images/water_elec_2.png"},{heading:"ئاوی ڕژاو لەسەر وایەرەکان",body:"ئەگەر بینیت ئاو ڕژاوەتە سەر وایەرێکی کارەبا یان پلاکێک، لێی نزیک مەبەرەوە و یەکسەر بە گەورەکان بڵێ بۆ ئەوەی کارەباکە ببڕن.",image:"media/images/water_elec_3.png"}],examples:["سێشوار (ئامێری وشککردنەوەی قژ) بە تەنیا بەکار مەهێنە، و هەرگیز مەیبە نزیک ئاو.","ئەگەر لە مەلەوانگە یان نزیک حەوز بوویت، دەست لە هیچ گڵۆپ یان ئامێرێکی کارەبایی مەدە.","ئەگەر زەوی تەڕ بوو، لە ئامێرە کارەباییەکان نزیک مەبەرەوە و بە کەسێکی گەورە بڵێ."],video:"media/videos/lesson07_water_elec.mp4",game:{instruction:"شێوازی دروست بۆ دەستدان لە سویچی کارەبا کامەیە؟",items:[{text:"بە دەستی تەڕ و ئاوی",emoji:"💦",correct:!1},{text:"بە دەستی پاک و وشک",emoji:"✋",correct:!0},{text:"بە دەستی سابوونی",emoji:"🧼",correct:!1},{text:"لە ناو بانیۆ",emoji:"🛁",correct:!1}]},activity:{prompt:"تازە لە حەمام دێیتە دەرەوە و دەستەکانت تەڕن، دەتەوێت گڵۆپی ژوورەکە هەڵبکەیت، چی دەکەیت؟",image:"media/images/activity_water_elec.png",options:[{text:"سەرەتا دەستەکانم بە خاولییەک وشک دەکەمەوە، پاشان گڵۆپەکە هەڵدەکەم",correct:!0,feedback:"پێش ئەوەی دەست لە سویچ بدەیت، دەبێت دەستەکانت بە تەواوی وشک بن، ئافەرین!"},{text:"هەر بە تەڕی دەست لە سویچی کارەبا دەدەم",correct:!1,feedback:"ئاو کارەبا دەگوازێتەوە، ئەگەر بە دەستی تەڕ دەست لە سویچ بدەیت، کارەبا دەتگرێت."},{text:"بە جلەکانم دەستەکانم وشک دەکەمەوە و دەستی لێ دەدەم",correct:!1,feedback:"دەبێت دەستەکانت بە تەواوی وشک بن، سەرەتا بە خاولی وشکیان بکەرەوە، پاشان دەست لە سویچ بدە."},{text:"هاوار دەکەم تا کەسێک دێت و بۆم هەڵدەکات",correct:!1,feedback:"دەتوانیت خۆت بە سەلامەتی بیکەیت، سەرەتا دەستەکانت بە خاولی وشک بکەرەوە."}]}},{id:8,icon:"Building",emoji:"🧗",accent:"#4f46e5",title:"مەترسییەکانی شوێنە بەرزەکان",subtitle:"خۆت لە کەوتن بپارێزە",summary:"سەرکەوتن بۆ سەر مێز و دیوارە بەرزەکان یاری نییە. لەشت ناسکە و کەوتن لە شوێنێکی بەرز دەتوانێت ئێسکەکانت بشکێنێت و زۆر ئازارت بدات.",blocks:[{heading:"مێز و کورسی بۆ دانیشتنن",body:"کورسی بۆ دانیشتنە و مێز بۆ نانخواردنە، نەک بۆ ئەوەی لەسەری ڕاوەستیت یان پێیدا بچیتە سەر دۆڵابەکان.",image:"media/images/heights_1.png"},{heading:"باڵکۆن و پەنجەرە مەترسیدارن",body:"هەرگیز بەسەر پەنجەرە یان دیواری باڵکۆندا خۆت مەنوشتێنەوە، چونکە دەکرێت بە ئاسانی هاوسەنگیت لە دەست بدەیت و بکەویت.",image:"media/images/heights_2.png"},{heading:"لەسەر زەوی یاری بکە",body:"هەمیشە لەسەر زەوی یان لە ناو باخچە یاری بکە، بۆ ئەوەی ئەگەر کەوتیشیت، زیانت پێ نەگات.",image:"media/images/heights_3.png"}],examples:["لەسەر قەنەفە و جێگا باز مەدە، چونکە لەوانەیە بە سەرتدا بکەویت.","هەرگیز بۆ سەیرکردنی دەرەوە مەچۆ سەر ئەو کورسییانەی نزیک پەنجەرەن.","ئەگەر شتێکت لە شوێنێکی بەرز بوو، هەوڵ مەدە بە تەنیا پێی بگەیت، بە باوکت یان دایکت بڵێ."],video:"media/videos/lesson08_heights.mp4",game:{instruction:"کام لەم شوێنانە بۆ یاری سەلامەتە؟",items:[{text:"لەسەر دیواری باڵکۆن",emoji:"🧱",correct:!1},{text:"لەسەر فەرشی ژوورەکە",emoji:"🏃",correct:!0},{text:"لەسەر مێزی نانخواردن",emoji:"🪟",correct:!1},{text:"لەسەر لقی درەختەکان",emoji:"🌳",correct:!1}]},activity:{prompt:"یارییە خۆشەویستەکەت کەوتووەتە سەر دۆڵابێکی بەرز و دەستت پێی ناگات، چی دەکەیت؟",image:"media/images/activity_heights.png",options:[{text:"بە کەسێکی گەورە دەڵێم و بە هێمنی چاوەڕێ دەکەم تا بۆم دەهێنێتە خوارەوە",correct:!0,feedback:"لەوانەیە لە شوێنی بەرز بکەویت، بۆیە داواکردنی یارمەتی لە کەسێکی گەورە زیرەکییە!"},{text:"خۆم دەچمە سەر دۆڵابەکە",correct:!1,feedback:"دۆڵاب بۆ سەرکەوتن نییە، لەوانەیە بکەویت، داوای یارمەتی لە کەسێکی گەورە بکە."},{text:"چەند کورسییەک دەخەمە سەر یەک بۆ ئەوەی پێی بگەم",correct:!1,feedback:"کورسی بۆ دانیشتنە، نەک بۆ سەرکەوتن، بە کەسێکی گەورە بڵێ بۆت بهێنێتە خوارەوە."},{text:"بە دارێک لێی دەدەم تا بکەوێتە خوارەوە و بشکێت",correct:!1,feedback:"لەوانەیە یارییەکەت بشکێت، بە کەسێکی گەورە بڵێ بۆت بهێنێتە خوارەوە."}]}},{id:9,icon:"Candy",emoji:"🍬",accent:"#db2777",title:"مەترسییەکانی قووتدان",subtitle:"شتە بچووکەکان و خنکان",summary:"دەممان بۆ خواردن و خواردنەوەیە. پێویستە زۆر وریا بین و هیچ شتێکی تر نەخەینە دەممانەوە، چونکە هەندێک شت دەتوانن ڕێگای هەناسەمان بگرن و بمانخنکێنن.",blocks:[{heading:"پارەی ئاسنین و مووروو",body:"پارەی ئاسنین، مووروو و پاترییە بچووکەکانی کاتژمێر بۆ خواردن نین. ئەگەر ئەم شتانە بچنە ناو گەروو، زۆر مەترسیدارن.",image:"media/images/swallow_1.png"},{heading:"دەرمان شیرینی نییە",body:"حەبی دەرمان ڕەنگی جوانیان هەیە و وەک شیرینی دەردەکەون، بەڵام ئەگەر خۆت بیانخۆیت، ژەهراوی دەبیت. تەنها کاتێک دایک یان باوک پێت دەدەن، دەرمان بخۆ.",image:"media/images/swallow_2.png"},{heading:"پاراستنی ڕێگای هەناسە",body:"هەر شتێک کە خواردن نەبێت و بیخەیتە دەمتەوە، دەتوانێت لە گەرووتدا گیر ببێت و نەهێڵێت هەناسە بدەیت. هەمیشە شتە بچووکەکان لە دەمت دوور بخەرەوە.",image:"media/images/swallow_3.png"}],examples:["سەری قەڵەم مەخەرە دەمتەوە، چونکە دەتوانێت بە ئاسانی بچێتە ناو گەرووتەوە.","ناوکی میوە (وەک قەیسی و زەیتوون) قووت مەدە، یەکسەر لە دەمت دەری بهێنە.","ئەگەر شتێکت قووت دا، یەکسەر بە گەورەکان بڵێ، تەنانەت ئەگەر باشیش بیت."],video:"media/videos/lesson09_swallow.mp4",game:{instruction:"کام لەم شتانە بۆ خواردن گونجاون؟",items:[{text:"سێو و میوە",emoji:"🍎",correct:!0},{text:"پارەی ئاسنین",emoji:"🪙",correct:!1},{text:"موورووی ڕەنگاوڕەنگ",emoji:"📿",correct:!1},{text:"نان و سەموون",emoji:"🍞",correct:!0}]},activity:{prompt:"بینیت خوشکە بچووکەکەت پاترییەکی بچووکی یاری خستە دەمییەوە، چی دەکەیت؟",image:"media/images/activity_swallow.png",options:[{text:"یەکسەر بە دەنگی بەرز بانگی دایکم دەکەم و پێی دەڵێم خوشکەکەم چی خستووەتە دەمییەوە",correct:!0,feedback:"قووتدانی پاترییە بچووکەکان زۆر مەترسیدارە، بۆیە بە خێرایی بانگی دایکت دەکەیت!"},{text:"پێی پێدەکەنم و سەیر دەکەم",correct:!1,feedback:"پاتری لە دەمدا مەترسیدارە، یەکسەر بە دەنگی بەرز بانگی دایکت بکە."},{text:"منیش یەکێک دەخەمە دەمی خۆمەوە",correct:!1,feedback:"پاتری خواردن نییە، هەرگیز مەیخەرە دەمتەوە."},{text:"چاوەڕێ دەکەم تا خوشکەکەم قووتی دەدات",correct:!1,feedback:"چاوەڕێکردن مەترسیدارە، یەکسەر بانگی دایکت بکە، پێش ئەوەی خوشکەکەت قووتی بدات."}]}},{id:10,icon:"MapPin",emoji:"🗺️",accent:"#9333ea",title:"ونبوون لە شوێنە قەرەباڵغەکان",subtitle:"ئەگەر لە دایک و باوکت جیا بوویتەوە",summary:"ئەگەر لە بازاڕ، لە مۆڵ یان لە سەیران لە خێزانەکەت جیا بوویتەوە و ون بوویت، مەترسە. تەنها پێویستە بزانیت چی بکەیت، بۆ ئەوەی دایک و باوکت بە زووترین کات بتدۆزنەوە.",blocks:[{heading:"لە شوێنی خۆت بوەستە",body:"ئەگەر بینیت دایک و باوکت لە دەوروبەرت نین، ڕامەکە و بەدوایاندا مەگەڕێ. لە شوێنی خۆت بوەستە، چونکە ئەوان بە زووترین کات لەو شوێنە بەدوای تۆدا دەگەڕێن و دەتدۆزنەوە.",image:"media/images/lost_1.png"},{heading:"داوای یارمەتی بکە",body:"ئەگەر کەس نەهات، لە نزیک خۆت پۆلیسێک، پاسەوانێکی مۆڵ، کارمەندێکی دووکان یان دایکێک کە منداڵی لەگەڵە بدۆزەوە و پێی بڵێ: من ون بووم.",image:"media/images/lost_2.png"},{heading:"زانیارییە گرنگەکانی تۆ",body:"هەوڵ بدە ناوی سیانیی خۆت و ژمارەی تەلەفۆنی دایکت یان باوکت لەبەر بکەیت، بۆ ئەوەی ئەوانەی یارمەتیت دەدەن بتوانن پەیوەندییان پێوە بکەن.",image:"media/images/lost_3.png"}],examples:["هەرگیز لە بازاڕ دەستی دایکت بەر مەدە.","هەرگیز لەگەڵ کەسانی نەناسراو مەچۆ هیچ شوێنێک، تەنانەت ئەگەر شیرینیشت پێ بدەن.","هێمن بە و مەگری، چونکە ترس ناهێڵێت باش بیر بکەیتەوە.","لە شوێنی ڕووناک و پڕ لە خەڵک بمێنەوە و مەچۆ ناو کۆڵانە تاریکەکان."],video:"media/videos/lesson10_lost.mp4",game:{instruction:"ئەگەر ون بوویت، کێ دەتوانێت یارمەتیت بدات؟",items:[{text:"پۆلیس یان پاسەوان",emoji:"👮‍♂️",correct:!0},{text:"کەسێکی نەناسراو",emoji:"👤",correct:!1},{text:"دایکێک کە منداڵی لەگەڵە",emoji:"👩‍👧‍👦",correct:!0},{text:"پیاوێکی ترسناک",emoji:"🦹‍♂️",correct:!1}]},activity:{prompt:"لە مۆڵێک ون بوویت و دایک و باوکت نابینیت، چی دەکەیت؟",image:"media/images/activity_lost.png",options:[{text:"لە شوێنی خۆم دەمێنمەوە و ناچمە هیچ شوێنێک تا ئەوان دێن، یان بە کەسێکی جێی متمانە دەڵێم",correct:!0,feedback:"مانەوە لە شوێنی خۆت یارمەتی دایک و باوکت دەدات بە خێرایی بتدۆزنەوە، ئافەرین!"},{text:"بە ڕاکردن بەرەو دەرگای مۆڵەکە دەچم و دەچمە دەرەوە",correct:!1,feedback:"ئەگەر بچیتە دەرەوە، لەوانەیە دایک و باوکت نەتدۆزنەوە، لە شوێنی خۆت بمێنەوە."},{text:"لەگەڵ کەسێکی نەناسراو دەچم چونکە دەڵێت دەتبەمە لای ئەوان",correct:!1,feedback:"هەرگیز لەگەڵ کەسێکی نەناسراو مەچۆ هیچ شوێنێک، لە شوێنی خۆت بمێنەوە."},{text:"دەچمە ژێر کورسییەک و خۆم دەشارمەوە",correct:!1,feedback:"ئەگەر خۆت بشاریتەوە، لەوانەیە دایک و باوکت نەتدۆزنەوە، لە نزیک خەڵک بمێنەوە."}]}},{id:11,icon:"Baby",emoji:"🎡",accent:"#65a30d",title:"سەلامەتی لە یاریگا",subtitle:"یاریکردن بە ڕێزەوە و بێ مەترسی",summary:"یاریگا شوێنێکی زۆر خۆشە بۆ یاریکردن و ناسینی هاوڕێی نوێ، بەڵام بۆ ئەوەی کەس بریندار نەبێت، پێویستە هەندێک یاسای زێڕین پەیڕەو بکەین.",blocks:[{heading:"هاوڕێکانت پاڵ مەنێ",body:"لەسەر جۆلانە یان خلیسکێنە، هەرگیز هاوڕێکانت پاڵ مەنێ، چونکە کەوتن لەسەر بەرد و زەویی ڕەق دەتوانێت برینی سەخت دروست بکات.",image:"media/images/playground_1.png"},{heading:"ڕیزبوون و نۆرەگرتن",body:"فێر بە چاوەڕێی نۆرەی خۆت بکەیت. نۆرەگرتن نیشانەی زیرەکی و ڕێزگرتنی تۆیە بۆ هاوڕێکانت.",image:"media/images/playground_2.png"},{heading:"سنووری یاریگا",body:"هەرگیز لە پەرژینی یاریگا مەچۆ دەرەوە. ئەگەر تۆپەکەت چووە دەرەوە، بە تەنیا بەدوایدا مەچۆ، بە دایکت یان مامۆستاکەت بڵێ.",image:"media/images/playground_3.png"}],examples:["لم مەهاوێژە بۆ هەوا، چونکە دەچێتە ناو چاوی هاوڕێکانت.","کاتێک جۆلانە دەجووڵێت لە پێشیدا مەوەستە، بۆ ئەوەی لێت نەدات.","ئەگەر بینیت یارییەک شکاوە، یاری پێ مەکە و بە بەرپرسی یاریگاکە بڵێ."],video:"media/videos/lesson11_playground.mp4",game:{instruction:"کام لەم ڕەفتارانە هی پاڵەوانی سەلامەتین؟",items:[{text:"پاڵنانی هاوڕێکان بۆ پێشکەوتن لە نۆرەدا",emoji:"✋",correct:!1},{text:"ڕاوەستان بە هێمنی لە ڕیزدا",emoji:"⏱️",correct:!0},{text:"شەڕکردن لەسەر یارییەکان",emoji:"🥊",correct:!1},{text:"یارمەتیدانی هاوڕێ بچووکترەکان",emoji:"🤝",correct:!0}]},activity:{prompt:"هاوڕێیەکت لە پێشتە و دەیەوێت بچێتە سەر یارییەکە، چی دەکەیت؟",image:"media/images/activity_playground.png",options:[{text:"بە هێمنی چاوەڕێ دەکەم تا نۆرەم دێت",correct:!0,feedback:"نۆرەگرتن نیشانەی زیرەکی و ڕێزگرتنی تۆیە بۆ هاوڕێکانت!"},{text:"پاڵی پێوە دەنێم بۆ ئەوەی من زووتر سەربکەوم",correct:!1,feedback:"پاڵنان دەتوانێت هاوڕێکەت بخاتە خوارەوە و بریندار بکات، چاوەڕێی نۆرەی خۆت بکە."},{text:"هاوار دەکەم و قیژە دەکەم",correct:!1,feedback:"هاوارکردن یارمەتی نادات، بە هێمنی چاوەڕێی نۆرەی خۆت بکە."},{text:"دەچمە شوێنێکی تر و لە پەرژینەکە دەپەڕمەوە",correct:!1,feedback:"هەرگیز لە پەرژینی یاریگا مەچۆ دەرەوە، لە ناو یاریگاکە چاوەڕێی نۆرەی خۆت بکە."}]}},{id:12,icon:"Dog",emoji:"🐕",accent:"#d97706",title:"ئاژەڵانی کۆڵان و نەناسراو",subtitle:"چۆنیەتیی مامەڵەکردن لەگەڵ سەگ و پشیلە",summary:"ئەو ئاژەڵانەی لە کۆڵان دەگەڕێن و خاوەنەکانیان ناناسین، دەتوانن مەترسیدار بن. هەندێکیان دەترسن یان نەخۆشن و دەتوانن گاز لە مرۆڤ بگرن.",blocks:[{heading:"دەست لە ئاژەڵی نەناسراو مەدە",body:"تەنانەت ئەگەر پشیلەیەک یان سەگێک زۆر جوانیش بێت، دەستی لێ مەدە. لەوانەیە گازت لێ بگرێت یان بە نینۆکەکانی بتڕووشێنێت، و دەتوانن نەخۆشیت پێ بگەیەنن.",image:"media/images/dogs_1.png"},{heading:"وەک دارێک ڕاوەستە",body:"ئەگەر سەگێک بەرەو تۆ هات: ڕامەکە! وەک دارێک بە بێدەنگی ڕاوەستە، دەستەکانت نزیک لەشت ڕابگرە و سەیری چاوی سەگەکە مەکە، تا ئەو دەڕوات.",image:"media/images/dogs_2.png"},{heading:"بە گەورەکان بڵێ",body:"ئەگەر ئاژەڵێکی بریندار یان تووڕەت لە نزیک ماڵ بینی، لێی نزیک مەبەرەوە و یەکسەر بە باوکت یان دایکت بڵێ. ئەگەر ئاژەڵێک گازی لێ گرتیت یان بە نینۆک بریندارت کرد، یەکسەر بە کەسێکی گەورە بڵێ بۆ ئەوەی بتبەنە لای پزیشک.",image:"media/images/dogs_3.png"}],examples:["هەرگیز بەرد و شت مەهاوێژە ئاژەڵەکان، چونکە تووڕە دەبن و هێرش دەکەنە سەرت.","کاتێک ئاژەڵەکان خواردن دەخۆن یان نووستوون، لێیان نزیک مەبەرەوە.","کلک و گوێی پشیلەکان مەکێشە، چونکە دەتڕووشێنن."],video:"media/videos/lesson12_dogs.mp4",game:{instruction:"ئەگەر سەگێکی نەناسراو بەرەو تۆ هات، چی دەکەیت؟",items:[{text:"بە خێرایی ڕادەکەم",emoji:"🏃",correct:!1},{text:"بەردی تێ دەگرم",emoji:"🪨",correct:!1},{text:"وەک دارێک بە بێدەنگی ڕادەوەستم",emoji:"🧍",correct:!0},{text:"هاوار دەکەم و دەستەکانم ڕادەوەشێنم",emoji:"🗣️",correct:!1}]},activity:{prompt:"پشیلەیەکی بچووک لەسەر شەقام دەگری، چی دەکەیت؟",image:"media/images/activity_dogs.png",options:[{text:"لە دوورەوە سەیری دەکەم و بە دایکم دەڵێم بۆ ئەوەی یارمەتیی بدات",correct:!0,feedback:"ئاژەڵی نەناسراو دەتوانێت گازت لێ بگرێت یان بتڕووشێنێت، بۆیە بە دایکت دەڵێیت یارمەتیی بدات!"},{text:"دەچم و یەکسەر باوەشی پێدا دەکەم",correct:!1,feedback:"تەنانەت پشیلەی جوانیش دەتوانێت گازت لێ بگرێت یان بتڕووشێنێت، دەستی لێ مەدە و بە دایکت بڵێ."},{text:"بە پێم پاڵی پێوە دەنێم",correct:!1,feedback:"پاڵنانی ئاژەڵ تووڕەی دەکات، بە دایکت بڵێ بۆ ئەوەی یارمەتیی بدات."},{text:"بەدوایدا ڕادەکەم و ڕاوی دەنێم",correct:!1,feedback:"ئەگەر بەدوای ئاژەڵدا ڕابکەیت، لەوانەیە گازت لێ بگرێت یان بتڕووشێنێت، بە دایکت بڵێ."}]}},{id:13,icon:"Wind",emoji:"👃",accent:"#475569",title:"ناسینەوەی بۆنی گاز و مەترسییەکانی",subtitle:"بۆن ئاگادارمان دەکاتەوە",summary:"هەندێک بۆن لە ناو ماڵدا وەک زەنگی ئاگادارکردنەوەن. بۆنی گاز یان بۆنی سووتان نیشانی دەدەن کە مەترسییەکی گەورە هەیە.",blocks:[{heading:"بۆنی هێلکەی گەنیو (گاز)",body:"گاز خۆی بێ بۆنە، بەڵام بە ئەنقەست بۆنێکی ناخۆشی تێ دەکەن بۆ ئەوەی بزانین ئەگەر گاز دزەی کرد. ئەگەر بۆنی گازت کرد، دەست لە هیچ سویچێکی کارەبا مەدە.",image:"media/images/gas_1.png"},{heading:"سەرەتا بچۆ دەرەوە",body:"مەوەستە بۆ کردنەوەی پەنجەرە. یەکسەر بچۆ دەرەوە و بە کەسێکی گەورە بڵێ. منداڵان هەرگیز دەست لە گاز نادەن.",image:"media/images/gas_2.png"},{heading:"لە باڵەخانەکە بچۆ دەرەوە",body:"لەو شوێنەی بۆنی لێ دێت مەمێنەوە. یەکسەر بچۆ دەرەوە و بە کەسێکی گەورە بڵێ. گەورەکان لە دەرەوە پەیوەندی بە ١١٥ دەکەن، نەک لە ناو ماڵەوە.",image:"media/images/gas_3.png"}],examples:["هەرگیز دەستکاریی سەمام و دوگمەکانی گاز مەکە.","لە گەراجی داخراوی ئۆتۆمبێلدا مەمێنەوە، چونکە دووکەڵی ئۆتۆمبێل ژەهراوییە.","ئەگەر بۆنی سووتانی وایەری کارەبات کرد، یەکسەر بە باوکت یان دایکت بڵێ."],video:"media/videos/lesson13_gas.mp4",game:{instruction:"ئەگەر لە چێشتخانە بۆنی گازت کرد، چی دەکەیت؟",items:[{text:"گڵۆپەکە هەڵدەکەم بۆ ئەوەی ببینم چی ڕوویداوە",emoji:"💡",correct:!1},{text:"بە کەسێکی گەورە دەڵێم",emoji:"🗣️",correct:!0},{text:"شقارتەیەک دادەگیرسێنم",emoji:"🔥",correct:!1},{text:"لە ماڵ دەچمە دەرەوە",emoji:"🚪",correct:!0}]},activity:{prompt:"تۆ لە چێشتخانەیت و بۆنێکی توندی گاز دێت، چی دەکەیت؟",image:"media/images/activity_gas.png",options:[{text:"یەکسەر دەچمە دەرەوە و بە کەسێکی گەورە دەڵێم",correct:!0,feedback:"بۆنی گاز مەترسییەکی گەورەیە، بۆیە یەکسەر دەچیتە دەرەوە و بە کەسێکی گەورە دەڵێیت!"},{text:"دەچمە نزیک تەباخەکە بۆ ئەوەی بزانم گازەکە لە کوێوە دێت",correct:!1,feedback:"منداڵان هەرگیز دەست لە گاز نادەن، یەکسەر بچۆ دەرەوە و بە کەسێکی گەورە بڵێ."},{text:"سویچی پانکەکە هەڵدەکەم بۆ ئەوەی بۆنەکە بڕوات",correct:!1,feedback:"کاتێک بۆنی گاز دێت، دەست لە هیچ سویچێک مەدە، بچۆ دەرەوە و بە کەسێکی گەورە بڵێ."},{text:"هیچ شتێک ناکەم و لە شوێنی خۆم دەمێنمەوە",correct:!1,feedback:"لەو شوێنەی بۆنی گازی لێ دێت مەمێنەوە، بچۆ دەرەوە و بە کەسێکی گەورە بڵێ."}]}},{id:14,icon:"FlaskConical",emoji:"🧴",accent:"#0d9488",title:"دەفر و شلە نەناسراوەکان",subtitle:"تامی مەکە و مەیخۆرەوە",summary:"لە ناو ماڵدا زۆر دەفر و بوتڵی ڕەنگاوڕەنگ هەن کە ڕەنگەکانیان وەک شەربەت جوانن، بەڵام لە ڕاستیدا مادەی کیمیایی و ژەهراوییان تێدایە کە بۆ پاککردنەوە بەکار دەهێنرێن.",blocks:[{heading:"مەیخۆرەوە و تامی مەکە",body:"هەر شلەیەک کە نایناسیت، هەرگیز تامی مەکە و مەیخۆرەوە. لەوانەیە دەرمانی پاککردنەوەی حەمام یان زەوی بێت و زیان بە لەشت بگەیەنێت.",image:"media/images/poison_1.png"},{heading:"هەمیشە پرسیار بکە",body:"پێش ئەوەی شتێکی نەناسراو بخۆیت یان بخۆیتەوە، لە دایکت یان باوکت بپرسە: ئایا ئەمە دەخورێت؟ ئەگەر ڕێگەیان پێ نەدایت، دەستی لێ مەدە.",image:"media/images/poison_2.png"},{heading:"مادەکانی پاککردنەوە مەترسیدارن",body:"کلۆر و دەرمانەکانی تری پاککردنەوە تەنها بۆ پاککردنەوەی ماڵن. هەندێکیان دەتوانن پێست و چاوەکانت بسووتێنن یان ژەهراویت بکەن.",image:"media/images/poison_3.png"}],examples:["دەرمانی مێروو و مێش و مێروولە ژەهرن، هەرگیز بۆنیان مەکە.","بوتڵی دەرمانەکانی ماڵ یاری نین، دەستیان لێ مەدە.","ئەگەر شتێکی نەناسراوت خواردەوە، یەکسەر بە دایکت یان باوکت بڵێ بۆ ئەوەی پەیوەندی بە ئەمبولانسەوە (١٢٢) بکەن."],video:"media/videos/lesson14_poison.mp4",game:{instruction:"کام لەم شتانە بۆ خواردنەوە گونجاون؟",items:[{text:"شەربەتی پرتەقاڵ",emoji:"🧃",correct:!0},{text:"دەرمانی پاککردنەوەی زەوی",emoji:"🧴",correct:!1},{text:"شلەی کلۆر",emoji:"🧪",correct:!1},{text:"شیری سپی",emoji:"🥛",correct:!0}]},activity:{prompt:"بوتڵێکی شینی جوانت لە ژێر دەستشۆرەکە بینی و تینووتە، چی دەکەیت؟",image:"media/images/activity_poison.png",options:[{text:"دەستی لێ نادەم و دەچمە لای دایکم و پرسیار دەکەم",correct:!0,feedback:"بوتڵی نەناسراو لەوانەیە ژەهری تێدا بێت، بۆیە سەرەتا لە دایکت دەپرسیت!"},{text:"کەمێک تامی دەکەم بۆ ئەوەی بزانم چییە",correct:!1,feedback:"تەنانەت کەمێکیش دەتوانێت زیانت پێ بگەیەنێت، هەرگیز تامی شلەیەکی نەناسراو مەکە."},{text:"دەیڕێژمە سەر زەوی و یاری پێ دەکەم",correct:!1,feedback:"مادەکانی پاککردنەوە دەتوانن پێست و چاو بسووتێنن، دەستی لێ مەدە و لە دایکت بپرسە."},{text:"دەیکەمە ناو پەرداخێک و دەیخۆمەوە",correct:!1,feedback:"لەوانەیە دەرمانی پاککردنەوە بێت و زیان بە لەشت بگەیەنێت، هەرگیز مەیخۆرەوە، لە دایکت بپرسە."}]}},{id:15,icon:"CloudRain",emoji:"🌧️",accent:"#0284c7",title:"باران و مەترسیی لافاو",subtitle:"خۆت لە ئاوی لافاو بپارێزە",summary:"باران بۆ ڕووەک و زەوی زۆر بەسوودە، بەڵام ئەگەر بارانێکی توند ببارێت، دەتوانێت ببێتە لافاو. ئاوی لافاو زۆر بەهێزە و دەتوانێت ژیانمان بخاتە مەترسییەوە.",blocks:[{heading:"لە ناو ماڵ بمێنەوە",body:"کاتێک بارانێکی بەهێز دەبارێت، باشترین و سەلامەتترین شوێن ناو ماڵە. لە ژێر بارانی توند یاری مەکە.",image:"media/images/flood_1.png"},{heading:"مەچۆ ناو ئاوی شەقام",body:"ئاوی لافاو پیسە و نەخۆشی هەڵدەگرێت. هەروەها زۆر بەهێزە، تەنانەت ئاوێکی کەمیش دەتوانێت بتخاتە سەر زەوی و لەگەڵ خۆیدا بتبات.",image:"media/images/flood_2.png"},{heading:"لە ڕووبار و جۆگەکان دوور بکەوەرەوە",body:"لە کاتی باراندا، ئاستی ئاوی ڕووبار و جۆگەکان بە خێرایی بەرز دەبێتەوە. هەمیشە لە کەناری ئاو دوور بکەوەرەوە.",image:"media/images/flood_3.png"}],examples:["ئەگەر بارانێکی توند باری و ئاو بەرز بووەوە، لەگەڵ گەورەکان لە شوێنە نزمەکانەوە بچنە شوێنە بەرزەکان.","لە کاتی باراندا چەتر بەکار بهێنە بۆ ئەوەی لەشت وشک بمێنێتەوە.","لە کاتی باراندا پێڵاوی لاستیکی لە پێ بکە، بەڵام هەرگیز مەچۆ ناو ئاوی لافاو."],video:"media/videos/lesson15_flood.mp4",game:{instruction:"کاتێک بارانێکی توند دەبارێت، کام شوێن لە هەموویان سەلامەتترە؟",items:[{text:"ناو باخچە",emoji:"🏕️",correct:!1},{text:"لە ناو ماڵ",emoji:"🏠",correct:!0},{text:"ناو ڕووبار",emoji:"🌊",correct:!1},{text:"لەسەر شەقام",emoji:"🛣️",correct:!1}]},activity:{prompt:"دەچیتە دەرەوە و دەبینیت هەموو شەقامەکە بووەتە ئاو و لافاو، چی دەکەیت؟",image:"media/images/activity_flood.png",options:[{text:"ناچمە ناو ئاوەکە، دەگەڕێمەوە ناو ماڵ و بە گەورەکان دەڵێم",correct:!0,feedback:"ئاوی لافاو بەهێز و پیسە، بۆیە گەڕانەوە بۆ ناو ماڵ سەلامەتترین کارە!"},{text:"دەچمە ناو ئاوی شەقامەکە و مەلە دەکەم",correct:!1,feedback:"ئاوی لافاو بەهێزە و دەتوانێت لەگەڵ خۆیدا بتبات، هەرگیز مەچۆ ناوی."},{text:"تەنها پێیەکانم دەخەمە ناوی و یاری دەکەم",correct:!1,feedback:"تەنانەت ئاوێکی کەمیش دەتوانێت بتخاتە سەر زەوی، بگەڕێوە ناو ماڵ."},{text:"تۆپەکەم فڕێ دەدەمە ناو ئاوەکە بۆ ئەوەی ئاوەکە بیبات",correct:!1,feedback:"لە ئاوی لافاو دوور بکەوەرەوە، بگەڕێوە ناو ماڵ و بە گەورەکان بڵێ."}]}},{id:16,icon:"Bus",emoji:"🚌",accent:"#ca8a04",title:"ئۆتۆمبێلە گەورەکان و خاڵە کوێرەکان",subtitle:"خۆت لە ناوچە مەترسیدارەکان دوور بخەرەوە",summary:"لۆری، پاس و ئۆتۆمبێلە گەورەکان وەک ئۆتۆمبێلە بچووکەکان نین. شۆفێرەکانیان هەندێک شوێنی دەوروبەری ئۆتۆمبێلەکە نابینن، کە پێیان دەڵێن خاڵە کوێرەکان (No-Zone). ئەگەر تۆ لەوێ بیت، شۆفێر ناتبینێت و لەوانەیە ئۆتۆمبێلەکە لێت بدات.",blocks:[{heading:"ناوچەی قەدەغە (No-Zone)",body:"لە پشتەوەی لۆری، لە پێشەوەی و لە هەردوو لاکەیدا خاڵی کوێر هەن. ئەگەر نەتوانیت چاوەکانی شۆفێر لە ئاوێنەکەدا ببینیت، ئەویش تۆ نابینێت. لە لۆری و پاس دوور بمێنەوە.",image:"media/images/car_back_1.png"},{heading:"ژێر ئۆتۆمبێل شوێنی یاری نییە",body:"ئەگەر تۆپ یان یارییەکەت چووە ژێر ئۆتۆمبێلێک (تەنانەت ئەگەر ڕاوەستاویش بێت)، بە هیچ شێوەیەک مەچۆ ژێر ئۆتۆمبێلەکە. یەکسەر بانگی کەسێکی گەورە بکە بۆ ئەوەی بۆت دەربهێنێت.",image:"media/images/car_back_2.png"},{heading:"مەودای سووڕانەوە",body:"کاتێک لۆری و پاس دەسووڕێنەوە، پێویستیان بە شوێنێکی گەورە هەیە و زۆر جار دەچنە سەر ڕێگای پیادەش. هەمیشە سێ هەنگاو لە کەناری شەقام دوور بوەستە.",image:"media/images/car_back_3.png"}],examples:["هەرگیز دەست یان سەرت لە پەنجەرەی پاس یان ئۆتۆمبێل دەرمەهێنە.","گەراج شوێنی یاری نییە، چونکە ئۆتۆمبێلەکان لەوێ دەچنە دواوە و شۆفێرەکان ناتبینن.","هەمیشە چاوەڕێ بکە تا پاسەکە بە تەواوی ڕادەوەستێت، پاشان دابەزە."],video:"media/videos/lesson16_car_back.mp4",game:{instruction:"کام شوێن لە نزیک ئۆتۆمبێلە گەورەکان مەترسیدارە؟",items:[{text:"ڕاستەوخۆ لە پشتەوەی لۆری",emoji:"🚘",correct:!0},{text:"ناو باخچە",emoji:"🌳",correct:!1},{text:"ڕاستەوخۆ لە پێشەوەی لۆری",emoji:"🚚",correct:!0},{text:"بە دووریی ١٠ مەتر",emoji:"🏠",correct:!1}]},activity:{prompt:"تۆپەکەت خلۆر بووەوە و چووە ژێر لۆرییەکی گەورە کە شۆفێری تێدایە، چی دەکەیت؟",image:"media/images/activity_car_back.png",options:[{text:"ناچمە ژێر لۆرییەکە و دەچمە لای باوکم بۆ ئەوەی ئەو بۆم دەربهێنێت",correct:!0,feedback:"شۆفێری لۆرییەکە تۆ نابینێت، بۆیە باوکت تۆپەکەت بۆ دەردەهێنێت!"},{text:"بە خێرایی دەچمە ژێر لۆرییەکە، چونکە شۆفێرەکە نووستووە",correct:!1,feedback:"هەرگیز مەچۆ ژێر لۆری، شۆفێرەکە تۆ نابینێت، بە باوکت بڵێ."},{text:"بە دارێکی درێژ لە تۆپەکە دەدەم تا دێتە دەرەوە",correct:!1,feedback:"لە لۆرییەکە دوور بمێنەوە، تەنانەت بە داریش، داوای یارمەتی لە باوکت بکە."},{text:"دەگریم تا شۆفێرەکە خۆی تۆپەکەم پێ دەداتەوە",correct:!1,feedback:"گریان یارمەتی نادات، لە لۆرییەکە دوور بمێنەوە و بە باوکت بڵێ."}]}},{id:17,icon:"Car",emoji:"🎗️",accent:"#4f46e5",title:"پشتێنی سەلامەتی و ئێرباگ",subtitle:"پاراستنی تۆ لە ناو ئۆتۆمبێلدا",summary:"پشتێنی سەلامەتی وەک باوەشێکی بەهێزە کە تۆ لەسەر کورسییەکە ڕادەگرێت. ئەگەر ئۆتۆمبێلەکە لەناکاو ڕاوەستا، ئەم پشتێنە ناهێڵێت لەشت بە توندی بەر شتەکان بکەوێت.",blocks:[{heading:"هەمیشە پشتێنەکە ببەستە",body:"پێش ئەوەی ئۆتۆمبێلەکە بجووڵێت، دەبێت لەسەر کورسیی تایبەتی منداڵان بیت و پشتێنەکەت بە دروستی ببەسترێت. ئەمە نیشانەی زیرەکیی تۆیە.",image:"media/images/seatbelt_1.png"},{heading:"شوێنی منداڵان لە دواوەیە",body:"ئەو منداڵانەی تەمەنیان لە ١٣ ساڵ کەمترە، دەبێت هەمیشە لەسەر کورسییەکانی دواوە دابنیشن. لە پێشەوە ئێرباگ (کیسەی هەوا) هەیە و کاتێک بە خێرایی دەتەقێتەوە، دەتوانێت زیان بە منداڵان بگەیەنێت.",image:"media/images/seatbelt_2.png"},{heading:"تا ئۆتۆمبێلەکە نەوەستێت مەجووڵێ",body:"هەرگیز پشتێنەکە مەکەرەوە و لە شوێنی خۆت مەجووڵێ، تا ئۆتۆمبێلەکە بە تەواوی ڕادەوەستێت و شۆفێرەکە ڕێگەت پێ دەدات.",image:"media/images/seatbelt_3.png"}],examples:["هەرگیز دەرگای ئۆتۆمبێل مەکەرەوە کاتێک ئۆتۆمبێلەکە بە ڕێوەیە.","کاتێک ئۆتۆمبێلەکە بە ڕێوەیە، بە دەنگی بەرز لەگەڵ شۆفێرەکە قسە مەکە بۆ ئەوەی سەرنجی تێک نەچێت.","لەسەر کورسیی دواوە یاریی توند مەکە، بۆ ئەوەی شۆفێرەکە سەرقاڵ نەبێت."],video:"media/videos/lesson17_seatbelt.mp4",game:{instruction:"کام ڕەفتار لە ناو ئۆتۆمبێلدا دروستن؟",items:[{text:"بەستنی پشتێنی سەلامەتی",emoji:"✅",correct:!0},{text:"دەرهێنانی سەر لە پەنجەرە",emoji:"🤪",correct:!1},{text:"دانیشتن لەسەر کورسیی دواوە",emoji:"💺",correct:!0},{text:"کردنەوەی دەرگا کاتێک ئۆتۆمبێلەکە بە ڕێوەیە",emoji:"🚪",correct:!1}]},activity:{prompt:"سواری ئۆتۆمبێل بوویت و دەتەوێت لەسەر کورسیی پێشەوە دابنیشیت، چی دەکەیت؟",image:"media/images/activity_seatbelt.png",options:[{text:"دەچمە سەر کورسیی دواوە و پشتێنەکە دەبەستم، چونکە بۆ منداڵان سەلامەتترە",correct:!0,feedback:"لە پێشەوە ئێرباگ هەیە و دەتوانێت زیان بە منداڵان بگەیەنێت، بۆیە کورسیی دواوە سەلامەتترە!"},{text:"دەگریم بۆ ئەوەی باوکم ڕێگەم بدات لە پێشەوە دابنیشم",correct:!1,feedback:"گریان کورسیی پێشەوە سەلامەت ناکات، لە دواوە دابنیشە و پشتێنەکە ببەستە."},{text:"پشتێنەکە نابەستم چونکە توندە",correct:!1,feedback:"پشتێن وەک باوەشێکی بەهێزە کە دەتپارێزێت، هەمیشە پشتێنەکە ببەستە."},{text:"کاتێک ئۆتۆمبێلەکە بە ڕێوەیە، دەرگاکە دەکەمەوە",correct:!1,feedback:"هەرگیز دەرگای ئۆتۆمبێل مەکەرەوە کاتێک بە ڕێوەیە، بە پشتێنی بەستراوەوە لە شوێنی خۆت بمێنەوە."}]}},{id:18,icon:"AlertTriangle",emoji:"☢️",accent:"#dc2626",title:"هێماکانی مەترسی لە هەموو جیهاندا",subtitle:"زمانی وێنەکان بناسە",summary:"لە هەموو جیهاندا هەندێک وێنە و هێمای تایبەت بەکار دەهێنرێن بۆ ئەوەی بێ قسەکردن لە مەترسی ئاگادارمان بکەنەوە. ناسینی ئەم هێمایانە نیشانەی زیرەکیی تۆیە.",blocks:[{heading:"کەللەسەر و ئێسک (ژەهر)",body:"ئەم هێمایە (☠️) نیشانەی مادەی ژەهراوی و کوشندەیە. هەر شتێک ئەم وێنەیەی لەسەر بێت، بە هیچ شێوەیەک دەستی لێ مەدە و لێی نزیک مەبەرەوە.",image:"media/images/danger_signs_1.png"},{heading:"هێمای بڵێسەی ئاگر (گڕگر)",body:"ئەم وێنەیە نیشانی دەدات کە ئەو مادەیە بە خێرایی ئاگر دەگرێت. دەبێت لە ئاگر و گەرمی دوور بێت، و تۆش دەستی لێ مەدە.",image:"media/images/danger_signs_2.png"},{heading:"بروسکەی زەرد (کارەبای بەهێز)",body:"ئەم هێمایە نیشانی دەدات کە لەم شوێنە کارەبایەکی زۆر بەهێز هەیە کە دەتوانێت مرۆڤ بکوژێت. هەرگیز لەو شوێنە نزیک مەبەرەوە.",image:"media/images/danger_signs_3.png"}],examples:["نیشانەی سووری X دەڵێت: ئەم کارە قەدەغەیە.","هێمای تیشک (☢️) لە هەندێک شوێنی نەخۆشخانەکان دەبینرێت، لەو شوێنانە دوور بکەوەرەوە.","هێما بازنەییە شینەکان ڕێنمایی سەلامەتین و دەبێت جێبەجێیان بکەین."],video:"media/videos/lesson18_danger_signs.mp4",game:{instruction:"ئەم هێمایە (☠️) چیمان پێ دەڵێت؟",items:[{text:"مادەی ژەهراوی و کوشندە",emoji:"🧪",correct:!0},{text:"ئاوی پاک بۆ خواردنەوە",emoji:"💧",correct:!1},{text:"خواردنی خۆش",emoji:"🍕",correct:!1},{text:"شوێنی یاریی منداڵان",emoji:"🎮",correct:!1}]},activity:{prompt:"وێنەی کەللەسەر و ئێسکت لەسەر دەرگای کۆگایەک بینی، چی دەکەیت؟",image:"media/images/activity_danger_signs.png",options:[{text:"یەکسەر لێی دوور دەکەومەوە، لە دەرگاکە نزیک نابمەوە و بە کەسێکی گەورە دەڵێم",correct:!0,feedback:"کەللەسەر و ئێسک نیشانەی ژەهرە، بۆیە دوور دەکەویتەوە و بە کەسێکی گەورە دەڵێیت!"},{text:"دەچمە ژوورەوە بۆ ئەوەی بزانم چی لەوێیە",correct:!1,feedback:"ئەم هێمایە نیشانەی ژەهرە، هەرگیز مەچۆ ژوورەوە، بە کەسێکی گەورە بڵێ."},{text:"بە بەرد لە دەرگاکە دەدەم",correct:!1,feedback:"لەو دەرگایە نزیک مەبەرەوە، ئەم هێمایە نیشانەی مەترسییە، بە کەسێکی گەورە بڵێ."},{text:"لەبەر دەرگاکە یاری دەکەم چونکە وێنەیەکی سەرنجڕاکێشە",correct:!1,feedback:"ئەم وێنەیە نیشانەی ژەهرە نەک یاری، دوور بکەوەرەوە و بە کەسێکی گەورە بڵێ."}]}},{id:19,icon:"Award",emoji:"🏆",accent:"#ca8a04",title:"پاڵەوانی سەلامەتی و بەرپرسیارێتی",subtitle:"تۆ ئێستا شارەزا و سەرکەوتوویت",summary:"دەستخۆش! تۆ زۆر یاسای سەلامەتیت فێر بوویت. ئێستا تۆ تەنها منداڵێک نیت، بەڵکو پاڵەوانێکی سەلامەتیت لە ناو کۆمەڵگاکەماندا.",blocks:[{heading:"تۆ هۆشیار و وریایت",body:"تۆ ئێستا دەزانیت چۆن خۆت لە مەترسییەکانی ئاگر، کارەبا، لافاو و شەقام بپارێزیت. ئەمە هێزی ڕاستەقینەی تۆیە.",image:"media/images/hero_1.png"},{heading:"یارمەتیی کەسانی تر بدە",body:"ئەرکی تۆ وەک پاڵەوان ئەوەیە کە ئەوەی فێری بوویت بە هاوڕێ، خوشک و براکانیشت بڵێیت، بۆ ئەوەی هەموویان پارێزراو بن.",image:"media/images/hero_2.png"},{heading:"پەیڕەوکردنی ڕێنماییەکانی سەلامەتی",body:"هەمیشە گوێ لە دایک و باوکت، مامۆستاکان و تیمەکانی بەرگریی شارستانی بگرە. یاساکانی سەلامەتی بۆ پاراستنی ژیانمانن.",image:"media/images/hero_3.png"}],examples:["هەمیشە پێش هەر کارێک بیر بکەرەوە: ئایا ئەمە سەلامەتە؟","ئەگەر مەترسییەکت بینی، بێ ترس بە گەورەکان بڵێ.","تۆ نموونەی زیرەکیت بۆ هەموو هاوڕێکانت."],video:"media/videos/lesson19_hero.mp4",game:{instruction:"ڕەفتارە دروستەکانی پاڵەوانی سەلامەتی کامانەن؟",items:[{text:"پاراستنی خۆت و کەسانی تر",emoji:"🛡️",correct:!0},{text:"یاریکردن بە شقارتە و چەقماخە",emoji:"🔥",correct:!1},{text:"یارمەتیدانی خێزان و هاوڕێکان",emoji:"🤝",correct:!0},{text:"شەڕکردن لەگەڵ هاوڕێکان",emoji:"👊",correct:!1}]},activity:{prompt:"بینیت هاوڕێیەکت لە باخچە دەیەوێت یاری بە وایەرێکی بڕاوی کارەبا بکات، چی دەکەیت؟",image:"media/images/activity_hero.png",options:[{text:"پێی دەڵێم: نزیک مەبەرەوە! و یەکسەر بە مامۆستاکەم یان دایکم دەڵێم",correct:!0,feedback:"وایەری بڕاو مەترسیدارە، بۆیە هاوڕێکەت ئاگادار دەکەیتەوە و بە کەسێکی گەورە دەڵێیت!"},{text:"منیش لەگەڵیدا یاری پێ دەکەم",correct:!1,feedback:"هەرگیز لە وایەری بڕاو نزیک مەبەرەوە، یەکسەر بە کەسێکی گەورە بڵێ."},{text:"لێی دەدەم بۆ ئەوەی ڕاوەستێت",correct:!1,feedback:"لێدان زیان بە هاوڕێکەت دەگەیەنێت، بە قسە ئاگاداری بکەرەوە و بە کەسێکی گەورە بڵێ."},{text:"بێدەنگ دەبم و هیچ ناڵێم",correct:!1,feedback:"پاڵەوانی سەلامەتی بێدەنگ نابێت، یەکسەر مەترسییەکە بە کەسێکی گەورە بڵێ."}]}},{id:20,icon:"Truck",emoji:"🚒",accent:"#dc2626",title:"پاڵەوانانی ئاگرکوژێنەوە",subtitle:"کارمەندانی بەڕێوەبەرایەتیی بەرگریی شارستانی",summary:"کارمەندانی بەرگریی شارستانی ئەو پاڵەوانانەن کە ڕاهێنانی سەختیان بینیوە، بۆ ئەوەی ئاگر بکوژێننەوە و ژیانی مرۆڤ و ئاژەڵ لە کاتی تەنگانەدا ڕزگار بکەن.",blocks:[{heading:"ئۆتۆمبێلی سووری ئاگرکوژێنەوە",body:"ئۆتۆمبێلی ئاگرکوژێنەوە سوورە و ئاو، پەیژە و ئامێری ڕزگارکردنی تێدایە. کاتێک دەنگی زەنگەکەی (سایرێن) دەبیستیت، دەبێت ڕێگای بۆ بکرێتەوە.",image:"media/images/firefighters_1.png"},{heading:"جلی پاراستن",body:"ئاگرکوژەکان جلی تایبەت لەبەر دەکەن کە ئاگر ناگرن و ناهێڵن گەرمی بگاتە لەشیان. هەروەها کڵاو و پێڵاوەکانیان زۆر بەهێزن.",image:"media/images/firefighters_2.png"},{heading:"یارمەتیدەرانی کۆمەڵگا",body:"ئاگرکوژەکان هاوڕێی ئێمەن. کاتێک مەترسییەک هەبێت، دێن بۆ ئەوەی بمانپارێزن. لە دەنگ، جل و دەمامکەکانیان مەترسە و خۆتیان لێ مەشارەوە، چونکە ئەوان بۆ ڕزگارکردنی تۆ دێن.",image:"media/images/firefighters_3.png"}],examples:["کاتێک دەنگی ئۆتۆمبێلی ئاگرکوژێنەوە دەبیستیت، لە شەقام دوور بکەوەرەوە و لە کەنارەوە بوەستە.","ئاگرکوژەکان تەنها ئاگر ناکوژێننەوە، بەڵکو خەڵکی گیرخواردووش ڕزگار دەکەن.","ئەوان کارێکی پیرۆز دەکەن بۆ پاراستنی خەڵکی شار."],video:"media/videos/lesson20_firefighters.mp4",game:{instruction:"کام لەم شتانە هی ئاگرکوژەکانن؟",items:[{text:"ئۆتۆمبێلی سووری ئاگرکوژێنەوە",emoji:"🚒",correct:!0},{text:"پاسی گشتی",emoji:"🚌",correct:!1},{text:"کڵاوی ڕەق و جلی ئاگرکوژەکان",emoji:"🧑‍🚒",correct:!0},{text:"پشیلەی یاری",emoji:"🐱",correct:!1}]},activity:{prompt:"بینیت ئۆتۆمبێلێکی سووری ئاگرکوژێنەوە بە خێرایی و بە دەنگی زەنگەوە دێت، چی دەکەیت؟",image:"media/images/activity_firefighters.png",options:[{text:"لە شەقام دوور دەکەومەوە و لە کەنارەوە ڕادەوەستم تا ئۆتۆمبێلەکە تێدەپەڕێت",correct:!0,feedback:"دەبێت ڕێگا بۆ ئۆتۆمبێلی ئاگرکوژێنەوە بکرێتەوە، بۆیە ڕاوەستان لە کەنارەوە یارمەتیدەرە!"},{text:"دەچمە ناوەڕاستی شەقام بۆ ئەوەی وێنەیەک بگرم",correct:!1,feedback:"ناوەڕاستی شەقام مەترسیدارە، لە کەنارەوە بوەستە."},{text:"بە ڕاکردن بەرەو ئۆتۆمبێلەکە دەچم",correct:!1,feedback:"ڕاکردن بەرەو ئۆتۆمبێلەکە مەترسیدارە، بچۆ لاوە و ڕێگای بۆ چۆڵ بکە."},{text:"بەرد دەهاوێمە ئۆتۆمبێلەکە",correct:!1,feedback:"ئاگرکوژەکان هاوڕێی ئێمەن و بۆ یارمەتی دێن، لە کەنارەوە بوەستە."}]}},{id:21,icon:"PhoneCall",emoji:"📞",accent:"#2563eb",title:"ژمارەی فریاکەوتن ١١٥",subtitle:"پەیوەندیکردن بە بەرگریی شارستانییەوە",summary:"١١٥ ژمارەی بەرگریی شارستانییە. کاتێک ئاگر یان کارەساتێک ڕوو دەدات، بەم ژمارەیە پەیوەندی دەکرێت و ئاگرکوژەکان بە خێرایی دێن. هەموو منداڵێک دەبێت ئەم ژمارەیە لەبەر بکات.",blocks:[{heading:"١١٥ بۆ تەنگانەیە",body:"ئەگەر ئاگرێکت بینی، یان کەسێک لە ژێر داڕماودا مایەوە، یان لافاو هات، یەکسەر بە کەسێکی گەورە بڵێ بۆ ئەوەی پەیوەندی بە ١١٥ بکات. ئەگەر هیچ کەسێکی گەورە لە لات نەبوو، خۆت لە شوێنێکی سەلامەتەوە پەیوەندی بە ١١٥ بکە. بۆ بریندار و نەخۆشەکان، گەورەکان پەیوەندی بە ئەمبولانسەوە (١٢٢) دەکەن.",image:"media/images/emergency_number_1.png"},{heading:"چۆنیەتیی قسەکردنی دروست",body:"کاتێک پەیوەندی دەکرێت، بە هێمنی قسە بکە و بڵێ: ناوت چییە، لە کوێیت و چی ڕوویداوە.",image:"media/images/emergency_number_2.png"},{heading:"یاری بەم ژمارەیە ناکرێت",body:"پەیوەندیکردن بە ١١٥ تەنها بۆ تەنگانەی ڕاستەقینەیە. یاریکردن بەم ژمارەیە قەدەغەیە، چونکە لەوانەیە تیمەکان درەنگ بگەنە ئەو کەسانەی پێویستیان بە یارمەتییە.",image:"media/images/emergency_number_3.png"}],examples:["ژمارەی ١١٥ لەبەر بکە: یەک، یەک، پێنج.","تەنها کاتێک مەترسییەکی ڕاستەقینە هەبێت، پەیوەندی بە ١١٥ دەکرێت.","کاتێک لەگەڵ ١١٥ قسە دەکەیت، تەلەفۆنەکە دامەخە تا کارمەندەکە پێت نەڵێت."],video:"media/videos/lesson21_emergency_number.mp4",game:{instruction:"ژمارەی فەرمیی بەرگریی شارستانی لە دهۆک چەندە؟",items:[{text:"١٢٣",emoji:"📱",correct:!1},{text:"١١٥",emoji:"🚒",correct:!0},{text:"٩٩٩",emoji:"📞",correct:!1},{text:"٤٤٤",emoji:"☎️",correct:!1}]},activity:{prompt:"لە کۆڵان بینیت دووکەڵ و بۆنێکی توندی سووتان لە ماڵێکەوە دێت، چی دەکەیت؟",image:"media/images/activity_emergency_number.png",options:[{text:"یەکسەر بە کەسێکی گەورە دەڵێم بۆ ئەوەی پەیوەندی بە ١١٥ بکات، ئەگەر کەس نەبوو، خۆم پەیوەندی بە ١١٥ دەکەم",correct:!0,feedback:"پەیوەندیکردن بە ١١٥ ئاگرکوژەکان بە خێرایی دەهێنێت، بۆیە یەکسەر کەسێکی گەورە ئاگادار دەکەیتەوە!"},{text:"لە شوێنی خۆم دەمێنمەوە و دەگریم",correct:!1,feedback:"گریان یارمەتی ناهێنێت، یەکسەر بە کەسێکی گەورە بڵێ بۆ ئەوەی پەیوەندی بە ١١٥ بکات."},{text:"دەچمە ناو ئەو ماڵە بۆ ئەوەی بزانم چی هەیە",correct:!1,feedback:"هەرگیز مەچۆ ناو ماڵێک کە دووکەڵی لێ دێت، لە دەرەوە بمێنەوە و بە کەسێکی گەورە بڵێ."},{text:"خۆم دەشارمەوە بۆ ئەوەی پۆلیس نەمگرێت",correct:!1,feedback:"خۆت مەشارەوە، یەکسەر بە کەسێکی گەورە بڵێ بۆ ئەوەی پەیوەندی بە ١١٥ بکات."}]}},{id:22,icon:"DoorOpen",emoji:"🚪",accent:"#16a34a",title:"پلانی دەرچوونی تەنگانە",subtitle:"ڕێگای دەرچوونی خێرا و هێمن",summary:"پلانی دەرچوون نەخشەیەکە کە نیشانی دەدات لە کاتی ئاگر یان مەترسیدا لە کام ڕێگاوە بچینە دەرەوە و لە کوێ کۆ ببینەوە. دەبێت بۆ هەموو ماڵێک و قوتابخانەیەک ئەم پلانە هەبێت، بۆ ئەوەی هەموو کەس بە هێمنی بچنە دەرەوە.",blocks:[{heading:"دوو ڕێگای دەرچوون",body:"بۆ هەموو ژوورێک دەبێت دوو ڕێگای دەرچوون هەبێت. ئەگەر ڕێگای یەکەم گیرا، لەگەڵ گەورەکان ڕێگای دووەم بەکار بهێنە.",image:"media/images/evacuation_1.png"},{heading:"خاڵی کۆبوونەوە",body:"دوای ئەوەی لە باڵەخانەکە چوویتە دەرەوە، بچۆ بۆ خاڵی کۆبوونەوە: شوێنێکی کراوە و سەلامەت کە پێشتر دیاری کراوە. لەوێ بمێنەوە بۆ ئەوەی گەورەکان بزانن هەموو کەس هاتوونەتە دەرەوە.",image:"media/images/evacuation_2.png"},{heading:"یاسای زێڕین: مەگەڕێوە ژوورەوە",body:"کاتێک لە باڵەخانەکە چوویتە دەرەوە، بە هیچ شێوەیەک مەگەڕێوە ژوورەوە، نە بۆ یارییەکان و نە بۆ هیچ شتێکی تر. ژیانی تۆ لە هەموو شتێک گرنگترە.",image:"media/images/evacuation_3.png"}],examples:["ساڵانە لانیکەم دوو جار، لەگەڵ خێزانەکەت ڕاهێنانی دەرچوون بکە.","لە باڵەخانە گشتییەکان، سەرنجی نیشانە سەوزەکانی دەرچوون (EXIT) بدە.","ئەگەر دووکەڵ هەبوو، لەسەر دەست و ئەژنۆ گاگۆڵکێ بکە، چونکە هەوای پاکتر لە نزیک زەوییە."],video:"media/videos/lesson22_evacuation.mp4",game:{instruction:"لە کاتی دەرچووندا، کام لەم کارانە دروستن؟",items:[{text:"زانینی ڕێگاکانی دەرچوون",emoji:"🚪",correct:!0},{text:"گەڕانەوە بۆ ناو باڵەخانەکە بۆ هێنانی یارییەکان",emoji:"🧸",correct:!1},{text:"مانەوە لە خاڵی کۆبوونەوە",emoji:"📍",correct:!0},{text:"مانەوە لە ژوورەکە تا تیمەکان دێن",emoji:"🛋️",correct:!1}]},activity:{prompt:"زەنگی ئاگر لە قوتابخانە لێی دا و یارییەکانت لە پۆلەکەدا مانەوە، چی دەکەیت؟",image:"media/images/activity_evacuation.png",options:[{text:"بە هێمنی و بێ پاڵنانی هاوڕێکانم، لەگەڵ مامۆستاکەم لە دەرگای دەرچوونەوە دەچمە دەرەوە",correct:!0,feedback:"چوونە دەرەوە بە هێمنی لەگەڵ مامۆستاکەت سەلامەتترین کارە، ژیانی تۆ لە یارییەکان گرنگترە!"},{text:"دەگەڕێمەوە پۆلەکە بۆ ئەوەی یارییەکانم بهێنم",correct:!1,feedback:"هەرگیز بۆ یارییەکان مەگەڕێوە، ژیانی تۆ لە هەموو شتێک گرنگترە."},{text:"دەچمە ژێر مێزێک و خۆم دەشارمەوە",correct:!1,feedback:"کاتێک زەنگی ئاگر لێ دەدات، خۆت مەشارەوە، لەگەڵ مامۆستاکەت بچۆ دەرەوە."},{text:"بە ڕاکردن و هاوارەوە بەرەو ئاسانسۆرەکە دەچم",correct:!1,feedback:"ئاسانسۆر بەکار مەهێنە، بە هێمنی لەگەڵ مامۆستاکەت لە دەرگای دەرچوونەوە بچۆ دەرەوە."}]}},{id:23,icon:"FireExtinguisher",emoji:"🧯",accent:"#ea580c",title:"ئامێر و کەرەستەکانی ئاگرکوژێنەوە",subtitle:"ئامێرەکانی ئاگرکوژەکان",summary:"تیمەکانی بەرگریی شارستانی ئامێری زۆر پێشکەوتوو بەکار دەهێنن بۆ کوژاندنەوەی ئاگر و ڕزگارکردنی خەڵک. ئەم ئامێرانە تەنها بۆ گەورەکان و ئاگرکوژەکانن، منداڵان دەستیان لێ نادەن.",blocks:[{heading:"ئاگرکوژێنەرەوە (ئامێری کوژاندنەوەی ئاگر)",body:"ئاگرکوژێنەرەوە بوتڵێکی پەستێنراوە، و ئاو، تۆز یان گازی CO₂ی تێدایە. تەنها گەورەکان بەکاری دەهێنن، منداڵان هەرگیز دەستی لێ نادەن.",image:"media/images/fire_equipment_1.png"},{heading:"لوولەی ئاوی بەهێز",body:"ئاگرکوژەکان لوولەی ئاوی زۆر بەهێز بەکار دەهێنن کە ئاوێک بە پەستانێکی زۆرەوە فڕێ دەدەن و ئاگر دەکوژێننەوە.",image:"media/images/fire_equipment_2.png"},{heading:"ئامێرەکانی بڕین و ڕزگارکردن",body:"ئەمانە ئامێری زۆر بەهێزن کە ئاگرکوژەکان ئاسنی ئۆتۆمبێلەکانیان پێ دەبڕن، بۆ ئەوەی خەڵکی گیرخواردوو و بریندارەکان ڕزگار بکەن.",image:"media/images/fire_equipment_3.png"}],examples:["هەرگیز دەست لە ئاگرکوژێنەرەوە مەدە، چونکە پەستانێکی زۆری تێدایە.","بزانە ئاگرکوژێنەرەوە لە ماڵ و لە قوتابخانە لە کوێیە، بەڵام دەستی لێ مەدە.","ئەگەر ئاگرێکی گەورە هەبوو، هەموو کەس لە باڵەخانەکە دەچنە دەرەوە و تەنها ئاگرکوژەکان ئامێرەکانیان بەکار دەهێنن."],video:"media/videos/lesson23_fire_equipment.mp4",game:{instruction:"کام لەم ئامێرانە بۆ کوژاندنەوەی ئاگر بەکار دەهێنرێن؟",items:[{text:"ئاگرکوژێنەرەوە",emoji:"🧯",correct:!0},{text:"تۆپی یاری",emoji:"⚽",correct:!1},{text:"لوولەی ئاوی ئاگرکوژەکان",emoji:"💦",correct:!0},{text:"کتێبی خوێندنەوە",emoji:"📚",correct:!1}]},activity:{prompt:"ئاگرێکی بچووک لە ناو سەتڵی زبڵی چێشتخانەکەدا هەڵگیرسا و باوکت لە ماڵە، چی دەکەیت؟",image:"media/images/activity_fire_equipment.png",options:[{text:"لە چێشتخانە دەچمە دەرەوە و بە دەنگی بەرز بانگی باوکم دەکەم بۆ ئەوەی ئەو ئاگرەکە بکوژێنێتەوە",correct:!0,feedback:"تەنها گەورەکان ئاگر دەکوژێننەوە، بۆیە بانگکردنی باوکت بە دەنگی بەرز کاری دروستە!"},{text:"ئاگرکوژێنەرەوەکە هەڵدەگرم و یاری پێ دەکەم",correct:!1,feedback:"ئاگرکوژێنەرەوە یاری نییە، تەنها گەورەکان بەکاری دەهێنن، بانگی باوکت بکە."},{text:"خۆم ئاو دەڕێژمە سەر ئاگرەکە",correct:!1,feedback:"منداڵان هەرگیز ئاگر ناکوژێننەوە، لە چێشتخانە بچۆ دەرەوە و بە دەنگی بەرز بانگی باوکت بکە."},{text:"دەچمە ژوورێکی تر و خۆم دەشارمەوە",correct:!1,feedback:"خۆشاردنەوە یارمەتی نادات، بە دەنگی بەرز بانگی باوکت بکە بۆ ئەوەی ئاگرەکە بکوژێنێتەوە."}]}},{id:24,icon:"CloudFog",emoji:"💨",accent:"#475569",title:"مەترسیی دووکەڵ و هەناسەدانی پاک",subtitle:"چۆنیەتیی دەرچوونی سەلامەت لە ناو دووکەڵ",summary:"دووکەڵی ئاگر زۆر جار لە خودی ئاگرەکە مەترسیدارترە، چونکە ژەهراوییە و ناهێڵێت مرۆڤ بە ئاسانی هەناسە بدات. دووکەڵ و گەرمی بەرز دەبنەوە، بۆیە هەوای پاکتر لە نزیک زەوییە. خۆت نزم بکەرەوە و بچۆ دەرەوە: ئەمە ژیانت ڕزگار دەکات.",blocks:[{heading:"خۆت نزم بکەرەوە و گاگۆڵکێ بکە",body:"گەرمی و دووکەڵ هەمیشە بەرز دەبنەوە، بۆیە هەوای پاکتر لە نزیک زەوی دەمێنێتەوە. لەسەر دەست و ئەژنۆ گاگۆڵکێ بکە و سەرت نزم ڕابگرە تا دەگەیتە دەرەوە. هەرگیز لە ناو دووکەڵدا بە پێوە مەڕۆ.",image:"media/images/smoke_1.png"},{heading:"پاراستنی دەم و لووت",body:"ئەگەر پارچە قوماشێکت پێ بوو، دەم و لووتی خۆتی پێ داپۆشە. بەڵام بۆ گەڕان بەدوای قوماشدا مەوەستە، چونکە قوماش ڕێگە لە هەموو دووکەڵەکە ناگرێت. یەکسەر خۆت نزم بکەرەوە و بچۆ دەرەوە.",image:"media/images/smoke_2.png"},{heading:"پێش کردنەوە، دەرگاکە تاقی بکەرەوە",body:"پێش ئەوەی دەرگاکە بکەیتەوە، بە پشتی دەستت دەست لە دەرگاکە و دەسکەکەی بدە. ئەگەر گەرم بوو، یان دووکەڵ لە ژێر دەرگاکەوە دەهات، مەیکەرەوە و ڕێگایەکی تر بەکار بهێنە.",image:"media/images/smoke_check_door.png"},{heading:"دەرگاکە لە پشت خۆتەوە دابخە",body:"کاتێک لە ژوورێک دەچیتە دەرەوە، دەرگاکە لە پشت خۆتەوە دابخە. دەرگای داخراو ناهێڵێت ئاگر و دووکەڵ بە خێرایی بچنە شوێنەکانی تر.",image:"media/images/smoke_3.png"},{heading:"بێ پێویست پەنجەرەکان مەکەرەوە",body:"هەوا ئاگر گەورەتر دەکات، بۆیە بێ پێویست پەنجەرە و دەرگاکان مەکەرەوە. ئەگەر لە ژوورێکدا گیرت خوارد، دەرگاکە داخراو بهێڵەوە، بچۆ بەر پەنجەرەکە، دەستت ڕاوەشێنە و هاوار بکە بۆ ئەوەی ئاگرکوژەکان بتبینن. هەرگیز خۆت لە پەنجەرە فڕێ مەدە.",image:"media/images/smoke_no_window.png"}],reference:[{heading:"یاسا سەرەکییەکان",points:["✅ خۆت نزم بکەرەوە و لەسەر دەست و ئەژنۆ گاگۆڵکێ بکە.","✅ ڕێگاکانی دەرچوونی ماڵەکەت بزانە.","✅ پێش کردنەوە، دەرگاکە بە پشتی دەست تاقی بکەرەوە، ئەگەر گەرم بوو مەیکەرەوە.","✅ دەرگاکە لە پشت خۆتەوە دابخە.","❌ خۆت لە ژێر تەخت یان لە ناو دۆڵاب مەشارەوە، و مەگەڕێوە ژوورەوە."]},{heading:"دوای دەرچوون",points:["🌿 بچۆ بۆ خاڵی کۆبوونەوە و لە دەرەوە بمێنەوە.","📞 بە کەسێکی گەورە بڵێ. گەورەکان لە دەرەوە پەیوەندی بە ١١٥ دەکەن، و بە ١٢٢یش ئەگەر کەسێک بریندار بوو.","⚠️ ئەگەر سەرت دێشێت، سەرت گێژ دەخوات یان بە زەحمەت هەناسە دەدەیت، یەکسەر بە کەسێکی گەورە بڵێ بۆ ئەوەی پەیوەندی بە ئەمبولانسەوە (١٢٢) بکات."]}],examples:["کاتێک دووکەڵ دەبینیت، هاوار بکە: ئاگر! پاشان خۆت نزم بکەرەوە و بەرەو ڕێگای دەرچوون گاگۆڵکێ بکە.","ئەگەر تاریک بوو، لەسەر دەست و ئەژنۆ بمێنەوە، دەستت بە دیوارەکەوە بگرە و بە نزمی بەرەو دەرگای دەرچوون گاگۆڵکێ بکە.","ئەگەر دەرگاکە گەرم بوو، مەیکەرەوە و ڕێگایەکی تر بەکار بهێنە.","ئەگەر نەتتوانی بچیتە دەرەوە: دەرگاکە دابخە، خاولییەک بخەرە ژێر دەرگاکە، لەبەر پەنجەرەکە دەستت ڕاوەشێنە و هاوار بکە. ئەگەر تەلەفۆنت پێ بوو، پەیوەندی بە ١١٥ بکە و بڵێ لە کوێیت."],video:"media/videos/lesson24_smoke.mp4",game:{instruction:"ئەگەر دووکەڵی ڕەش لە ژوورەکەدا هەبوو، چی دەکەیت؟ (هەموو وەڵامە دروستەکان هەڵبژێرە)",items:[{text:"بە پێوە ڕادەوەستم و دەمێنمەوە",emoji:"🧍",correct:!1},{text:"خۆم نزم دەکەمەوە و لەسەر دەست و ئەژنۆ گاگۆڵکێ دەکەم",emoji:"🧎",correct:!0},{text:"پەنجەرەکان دەکەمەوە بۆ ئەوەی هەوا بێت",emoji:"🪟",correct:!1},{text:"ئەگەر قوماشێکم پێ بێت، دەم و لووتی خۆمی پێ دادەپۆشم",emoji:"🧣",correct:!0},{text:"پێش کردنەوە، بە پشتی دەست دەرگاکە تاقی دەکەمەوە",emoji:"🖐️",correct:!0},{text:"دەرگاکە لە پشت خۆمەوە دادەخەم",emoji:"🚪",correct:!0}]},activity:{prompt:"لە ژووری نووستندایت و دووکەڵی ڕەش لە ژێر دەرگاکەوە دێتە ژوورەوە. دەرگاکە زۆر گەرمە. چی دەکەیت؟",image:"media/images/activity_smoke.png",options:[{text:"دەرگاکە ناکەمەوە، خۆم نزم دەکەمەوە، دەچمە بەر پەنجەرەکە، دەستم ڕادەوەشێنم و هاوار دەکەم بۆ ئەوەی گەورەکان و ئاگرکوژەکان بمبینن",correct:!0,feedback:"دەرگای گەرم نابێت بکرێتەوە، بۆیە لەبەر پەنجەرەکە دەستت ڕادەوەشێنیت و هاوار دەکەیت!"},{text:"دەرگاکە دەکەمەوە و بە پێوە ڕادەکەمە دەرەوە",correct:!1,feedback:"هەرگیز دەرگای گەرم مەکەرەوە، خۆت نزم بکەرەوە و بچۆ بەر پەنجەرەکە."},{text:"هەموو پەنجەرە و دەرگاکان دەکەمەوە بۆ ئەوەی ئاگرەکە کەم ببێتەوە",correct:!1,feedback:"هەوا ئاگر گەورەتر دەکات، دەرگاکە داخراو بهێڵەوە و لەبەر پەنجەرەکە دەستت ڕاوەشێنە."},{text:"لە ژێر تەختەکە خۆم دەشارمەوە",correct:!1,feedback:"ئاگرکوژەکان لە ژێر تەختەکە تۆ نابینن، لەبەر پەنجەرەکە دەستت ڕاوەشێنە و هاوار بکە."}]}},{id:25,icon:"Siren",emoji:"🚒",accent:"#dc2626",title:"ئاگرکوژە قارەمانەکان",subtitle:"ئەوانە کێن کە لە ناو ئۆتۆمبێلە سوورەکەدان؟",summary:"کاتێک ئاگرێک هەڵدەگیرسێت یان ڕووداوێک ڕوو دەدات، قارەمانەکانی بەرگریی شارستانی بە ئۆتۆمبێلە سوورەکە دێن! ئەوان ژیانی خەڵک دەپارێزن. ژمارەکەیان ١١٥یە، و هەموو منداڵێک دەبێت ئەم ژمارەیە بزانێت.",blocks:[{heading:"ئۆتۆمبێلە سوورەکە",body:"ئۆتۆمبێلی ئاگرکوژەکان گەورە و سوورە و سایرێنی هەیە. ئاو، لوولە، پەیژە و ئامێری ڕزگارکردنی تێدایە. کاتێک دەیبینیت، لە شەقام دوور بکەوەرەوە و ڕێگای بۆ چۆڵ بکە.",image:"media/images/cd_truck.png"},{heading:"سایرێنی قارەمانەکان",body:'دەنگی سایرێن "ووو-ووو-ووو" دەڵێت: "ئێمە دێین، ڕێگا بکەنەوە!" لێی مەترسە، ئەوان بۆ یارمەتیدانی ئێمە دێن.',image:"media/images/cd_siren.png"},{heading:"١١٥ ژمارەیەکی گرنگە",body:"ئەگەر ئاگرێک یان ڕووداوێکت بینی، یەکسەر بە کەسێکی گەورە بڵێ بۆ ئەوەی پەیوەندی بە ١١٥ بکات. ئەگەر بە تەنیا بوویت، لەسەر تەلەفۆن ١-١-٥ لێ بدە و ناوی خۆت و شوێنەکەت بڵێ.",image:"media/images/cd_phone.png"}],examples:["ئاگرکوژەکان جل و کڵاوی تایبەت لەبەر دەکەن بۆ ئەوەی ئاگر نەیانسووتێنێت.","کاتێک ئۆتۆمبێلە سوورەکە دێت، دەبێت ئۆتۆمبێلەکەی ئێمە بچێتە لاوە و ڕێگای بۆ چۆڵ بکات.","پەیوەندیکردن بە ١١٥ یاری نییە، تەنها بۆ تەنگانەی ڕاستەقینەیە."],video:"media/videos/lesson25_heroes.mp4",game:{instruction:"قارەمانەکانی بەرگریی شارستانی چ کارێک دەکەن؟",items:[{text:"ئاگر دەکوژێننەوە",emoji:"🔥",correct:!0},{text:"پیتزا دەفرۆشن",emoji:"🍕",correct:!1},{text:"خەڵکی گیرخواردوو ڕزگار دەکەن",emoji:"🆘",correct:!0},{text:"تۆپی پێ یاری دەکەن",emoji:"⚽",correct:!1},{text:"بە پەیژە سەردەکەون بۆ ئەوەی خەڵک ڕزگار بکەن",emoji:"🪜",correct:!0}]},activity:{prompt:"لەبەر پەنجەرەکەیت و ئۆتۆمبێلە سوورەکەت لەسەر شەقام بینی و دەنگی سایرێنەکەت بیست. چی دەکەیت؟",image:"media/images/activity_truck.png",options:[{text:"لە شوێنی خۆم دەمێنمەوە و بە دایکم یان باوکم دەڵێم: ئۆتۆمبێلی ئاگرکوژەکان هات!",correct:!0,feedback:"مانەوە لە شوێنی خۆت دەتپارێزێت و ڕێگا بۆ ئۆتۆمبێلەکە چۆڵ دەهێڵێتەوە!"},{text:"ڕادەکەمە سەر شەقام بۆ ئەوەی سەیر بکەم",correct:!1,feedback:"دەبێت شەقام بۆ ئۆتۆمبێلەکە چۆڵ بێت، لە شوێنی خۆت بمێنەوە."},{text:"پێڵاوەکەم فڕێ دەدەمە ئۆتۆمبێلەکە",correct:!1,feedback:"ئاگرکوژەکان بۆ یارمەتیدانی ئێمە دێن، هەرگیز شت مەهاوێژە ئۆتۆمبێلەکە."},{text:"دەترسم و خۆم لە ئاگرکوژەکان دەشارمەوە",correct:!1,feedback:"لە دەنگی سایرێن مەترسە، ئاگرکوژەکان بۆ یارمەتیدانی ئێمە دێن!"}]}},{id:26,icon:"FireExtinguisher",emoji:"🧯",accent:"#dc2626",title:"بوتڵە سوورەکەی ئاگرکوژێنەوە",subtitle:"ئاگرکوژێنەرەوە چییە؟",summary:"لە ماڵ، قوتابخانە و فەرمانگەکان بوتڵێکی سوور و گرنگ هەیە، ناوی ئاگرکوژێنەرەوەیە. گەورەکان ئاگری بچووکی پێ دەکوژێننەوە. تۆ بەکاری ناهێنیت، بەڵام باشە بزانیت چییە و لە کوێیە.",blocks:[{heading:"تەنها بۆ گەورەکانە",body:"ئاگرکوژێنەرەوە قورسە و پەستانێکی بەهێزی تێدایە. منداڵان هەرگیز ئاگرکوژێنەرەوە بەکار ناهێنن. ئەگەر ئاگرێک هەڵگیرسا، لەوێ بچۆ دەرەوە و بە دەنگی بەرز بانگی کەسێکی گەورە بکە.",image:"media/images/ext_adult.png"},{heading:"جۆری جیاواز، بەکارهێنانی جیاواز",body:"ئاگرکوژێنەرەوە جۆری جیاوازی هەیە. تەنها لە ڕەنگەکەیەوە بڕیار مەدە؛ نووسین و نیشانەکانی سەری بەکارهێنانی دیاری دەکەن. گەورەیەکی ڕاهێنراو جۆری گونجاو هەڵدەبژێرێت. تۆ دوور بکەوە و گەورەیەک ئاگادار بکەرەوە.",image:"media/images/ext_colors.png"},{heading:"ئاگرکوژێنەرەوەی ماڵەکەتان لە کوێیە؟",body:'لە دایک و باوکت بپرسە: "ئاگرکوژێنەرەوەی ماڵەکەمان لە کوێیە؟" زۆر جار لە نزیک دەرگای چێشتخانە یان لە ڕاڕەوەکەیە. بزانە لە کوێیە، بەڵام دەستی لێ مەدە.',image:"media/images/ext_location.png"}],examples:["ئاگرکوژێنەرەوە قورسە و ناتوانیت هەڵیبگریت، ئەو بۆ گەورەکانە.","ئەگەر ئاگر لە پلاکێک یان ئامێرێکی کارەبایی هەبوو، ئاو مەڕێژە سەری! کارەبا دەتگرێت. یەکسەر بە کەسێکی گەورە بڵێ.","گەورەکان هەموو مانگێک ئاگرکوژێنەرەوەکە دەپشکنن و ساڵی جارێک دەیبەنە لای پسپۆڕ، بۆ ئەوەی هەمیشە ئامادە بێت."],video:"media/videos/lesson26_extinguisher.mp4",game:{instruction:"کاتێک ئاگرێکی بچووک دەبینیت، چی دەکەیت؟",items:[{text:"هاوار دەکەم: ئاگر! و بە خێرایی دەچمە دەرەوە",emoji:"🏃",correct:!0},{text:"هەوڵ دەدەم ئاگرکوژێنەرەوەکە بەکار بهێنم",emoji:"🧯",correct:!1},{text:"کەسێکی گەورە ئاگادار دەکەمەوە",emoji:"👨",correct:!0},{text:"خۆم ئاو دەڕێژمە سەر ئاگرەکە",emoji:"💧",correct:!1}]},activity:{prompt:'بوتڵە سوورەکە لە ڕاڕەوەکەدا دەبینیت. هاوڕێکەت دەڵێت: "وەرە با یاری پێ بکەین!" چی دەکەیت؟',image:"media/images/activity_ext.png",options:[{text:"پێی دەڵێم: نا! ئەمە یاری نییە، ئەمە بۆ ئاگرە. پاشان بە کەسێکی گەورە دەڵێم",correct:!0,feedback:"ئاگرکوژێنەرەوە یاری نییە، بۆیە کەسێکی گەورە ئاگادار دەکەیتەوە!"},{text:"پێکەوە یاری پێ دەکەین",correct:!1,feedback:"ئاگرکوژێنەرەوە یاری نییە، تەنها بۆ گەورەکانە."},{text:"سنجاقی سەلامەتییەکەی دەردەکێشم",correct:!1,feedback:"هەرگیز سنجاقی سەلامەتی دەرمەکێشە، تەنها گەورەکان ئاگرکوژێنەرەوە بەکار دەهێنن."},{text:"پاڵی پێوە دەنێم تا بکەوێتە سەر زەوی",correct:!1,feedback:"ئاگرکوژێنەرەوە قورسە و پەستانێکی بەهێزی تێدایە، دەستی لێ مەدە و بە کەسێکی گەورە بڵێ."}]}},{id:27,icon:"HeartHandshake",emoji:"❤️‍🩹",accent:"#db2777",title:"یارمەتیدانی هاوڕێی بریندار",subtitle:"ئەگەر هاوڕێیەکت کەوت، چی دەکەیت؟",summary:"کاتێک هاوڕێیەکت دەکەوێت یان بریندار دەبێت، دەتوانیت یارمەتیی بدەیت. تۆ پزیشک نیت، بەڵام دەتوانیت هێمن بمێنیتەوە و بە خێرایی بە کەسێکی گەورە بڵێیت. گەورەکان دەزانن چی بکەن، و ئەگەر پێویست بوو، پەیوەندی بە ئەمبولانسەوە (١٢٢) دەکەن.",blocks:[{heading:"یەکەم: هێمن بمێنەوە",body:'گریان یارمەتی نادات. لە نزیک هاوڕێکەت بمێنەوە و بپرسە: "باشیت؟" پاشان پێی بڵێ: "مەترسە، من بانگی کەسێکی گەورە دەکەم."',image:"media/images/help_calm.png"},{heading:"دووەم: بانگی کەسێکی گەورە بکە",body:'بە خێرایی و بە دەنگی بەرز بانگ بکە: "مامۆستا!" یان "دایە!" ئەگەر هیچ کەسێکی گەورە لە نزیک نەبوو، بە خێرایی بڕۆ و کەسێکی گەورە بهێنە. کەسە گەورەکە ئەگەر پێویست بوو پەیوەندی بە ئەمبولانسەوە (١٢٢) دەکات.',image:"media/images/help_call.png"},{heading:"سێیەم: یارمەتیی بچووک",body:`تا کەسە گەورەکە دێت، دەتوانیت ئەم کارانە بکەیت:

• 🩸 خوێن: پارچە قوماشێکی پاک بدە بە هاوڕێکەت بۆ ئەوەی خۆی بە توندی لەسەر برینەکە ڕایبگرێت.
• 🦴 ئەگەر دەست یان قاچی زۆر دێشێت: هاوڕێکەت مەجووڵێنە.
• 🔥 سووتان: بە کەسێکی گەورە بڵێ، ئەو شوێنە سووتاوەکە ٢٠ خولەک لە ژێر ئاوی فێنکدا ڕادەگرێت. سەهۆڵ و هەویری ددان بۆ سووتان باش نین.`,image:"media/images/help_basic.png"}],examples:["ئەگەر سەر یان ملی هاوڕێکەت دێشێت، مەیجووڵێنە و مەهێڵە هەستێتەوە، چاوەڕێی کەسێکی گەورە بکەن.","دەست لە خوێنی کەسانی تر مەدە، و دوای یارمەتیدان دەستەکانت بە ئاو و سابوون بشۆ.","ئەگەر ترسایت، بانگی کەسێکی گەورە بکە. داواکردنی یارمەتی نیشانەی زیرەکییە."],video:"media/videos/lesson27_first_aid.mp4",game:{instruction:"کام لەم کارانە بۆ هاوڕێی بریندار دروستن؟",items:[{text:"هێمن دەمێنمەوە و بانگی گەورەکان دەکەم",emoji:"🧘",correct:!0},{text:"دەگریم و ڕادەکەم",emoji:"😭",correct:!1},{text:"پارچە قوماشێکی پاکی دەدەمێ بۆ ئەوەی لەسەر برینەکە ڕایبگرێت",emoji:"🩹",correct:!0},{text:"پێی پێدەکەنم و یاری دەکەم",emoji:"🤡",correct:!1},{text:"بە کەسێکی گەورە دەڵێم بۆ ئەوەی پەیوەندی بە ئەمبولانسەوە (١٢٢) بکات",emoji:"📞",correct:!0}]},activity:{prompt:'هاوڕێکەت لە قوتابخانە لە پلیکانەکان کەوت و دەڵێت: "قاچم دێشێت!" چی دەکەیت؟',image:"media/images/activity_help.png",options:[{text:"پێی دەڵێم: هێمن بە! پاشان بانگی مامۆستا دەکەم و هاوڕێکەم ناجووڵێنم.",correct:!0,feedback:"هێمن مانەوە، بانگکردنی مامۆستا و نەجووڵاندنی هاوڕێکەت باشترین یارمەتییە!"},{text:"هەوڵ دەدەم هەڵیبگرم و بیبەمە چێشتخانە",correct:!1,feedback:"ئەگەر قاچی زۆر دێشێت، هاوڕێکەت مەجووڵێنە، بانگی مامۆستا بکە."},{text:"قاچی دەکێشم بۆ ئەوەی بزانم شکاوە یان نا",correct:!1,feedback:"هەرگیز قاچی بریندار مەکێشە، هاوڕێکەت مەجووڵێنە و بانگی مامۆستا بکە."},{text:"دەچمەوە ماڵ و هیچ ناڵێم",correct:!1,feedback:"هاوڕێکەت پێویستی بە یارمەتییە، لە نزیکی بمێنەوە و یەکسەر بانگی کەسێکی گەورە بکە."}]}}],t={lessons:e};export{t as default,e as lessons};
